	enemyUnits.nameplate40.dead = nil
	clock = clock + 60
	Fire("UNIT_HEALTH", "nameplate40")
	enemyUnits.nameplate41 = { guid = "Player-9-ATTACKER", name = "Alliance Attacker", class = "ROGUE", level = 30 }
	Fire("NAME_PLATE_UNIT_ADDED", "nameplate41")
