	end
	enemyUnits.nameplate42 = { guid = "Player-9-SKYSEEN", name = "Sky Seen", class = "HUNTER", level = 30, raceName = "High Order Skyborne", raceFile = "Skyborne" }
	Fire("NAME_PLATE_UNIT_ADDED", "nameplate42")
