	-- At login, without the app, a popup offers it (like TSM's); "Don't remind me" stops it for good
	WantedAppInfo = nil
	ns.db.settings.appPrompt = true
	lastDialog = nil
	-- An earlier test left a dialog open; the popup never goes over another one
	local shown = ns.Widgets.IsDialogShown
	ns.Widgets.IsDialogShown = function() return true end
	ns:PromptForApp()
	check(lastDialog == nil, "the popup waits while another dialog is open")
	ns.Widgets.IsDialogShown = function() return false end
	ns:PromptForApp()
	check(lastDialog and lastDialog.title == "Get the Wanted app" and lastDialog.input and lastDialog.input.value == "https://wanteddeadordead.com/app",
		"without the app, a popup offers it with the address to copy")
	lastDialog.onCancel()
	lastDialog = nil
	check(ns.db.settings.appPrompt == false, "Don't remind me turns it off")
	ns:PromptForApp()
	check(lastDialog == nil, "and it doesn't come back")
	ns.db.settings.appPrompt = true
	WantedAppInfo = { running = "0.2.0", latest = "0.2.0" }
	ns:PromptForApp()
	check(lastDialog == nil, "with the app set up, no popup")
	-- Ten minutes in with no app detected: one line on what it brings and where to get it, once a day
	do
		local function Said() for i = #printed, 1, -1 do if tostring(printed[i]):find("No Wanted app detected after 10 minutes", 1, true) then return i end end end
		WantedAppInfo = nil
		ns.db.appNudgedAt = nil
		-- An earlier test took in an app catch-up, which counts as the app: this computer has none
		local hadApp = ns.Challenges.HasApp
		ns.Challenges.HasApp = function() return false end
		local before = #printed
		ns:NudgeForApp()
		local at = Said()
		check(at and at > before and tostring(printed[at]):find("wanteddeadordead.com/app", 1, true), "without the app, the ten-minute line says what it brings and where to get it")
		ns:NudgeForApp()
		check(Said() == at, "not twice a day")
		ns.db.appNudgedAt = GetServerTime() - 25 * 3600
		ns:NudgeForApp()
		check(Said() > at, "the next day it comes again")
		at = Said()
		ns.db.appNudgedAt = nil
		ns.db.settings.appPrompt = false
		ns:NudgeForApp()
		check(Said() == at, "not with reminders off")
		ns.db.settings.appPrompt = true
		WantedAppInfo = { running = "0.2.0", latest = "0.2.0" }
		ns:NudgeForApp()
		check(Said() == at and ns.db.appNudgedAt == nil, "not with the app")
		ns.Challenges.HasApp = hadApp
	end
	-- Set up, but it hadn't run for hours when the game read its file: the popup asks whether it's running, and
	-- the light says so (1790270000 is the clock when the addon loaded)
	WantedAppInfo = { running = "0.2.1", latest = "0.2.1", seen = 1790270000 - 5 * 3600, apps = 12 }
	ns:PromptForApp()
	check(lastDialog and lastDialog.title == "Is the Wanted app running?" and lastDialog.text:find("Start menu", 1, true) and lastDialog.text:find("Applications on a Mac", 1, true),
		"an app that hasn't run for hours: the popup asks if it's running")
	lastDialog = nil
	ns.UI:Show("board")
	ns.UI:Refresh()
	local function AppLight()
		for _, f in ipairs(Mock.created) do
			local text = rawget(f, "text")
			if rawget(f, "dot") and type(text) == "table" and tostring(text._text):find("^App") then return text._text end
		end
	end
	check(AppLight() == "App not running", "and the light says it isn't running, got "..tostring(AppLight()))
	local appStep = ns.Setup:Steps()[2]
	check(appStep.state == "warn" and appStep.fix:find("Applications on a Mac", 1, true), "how to start it, on Windows or a Mac: "..tostring(appStep.fix))
	local lightTip
	for _, f in ipairs(Mock.created) do
		if rawget(f, "tooltipTitle") == "The Wanted app isn't running" then lightTip = f.tooltipText end
	end
	check(lightTip and lightTip:find("Applications on a Mac", 1, true), "and the light's tooltip says the same")
	-- Running (seen within the half hour it writes): no popup; a development build counts the apps running
	WantedAppInfo.seen = clock - 600
	ns:PromptForApp()
	check(lastDialog == nil, "a running app: no popup")
	-- An app that said it quit (stopped, from 0.2.55) isn't running, however fresh its time
	WantedAppInfo.stopped = 1
	check(ns:AppNotRunningFor() ~= nil and ns:AppNotRunningFor() >= 1, "an app that said it quit: not running")
	WantedAppInfo.stopped = nil
	check(ns:AppNotRunningFor() == nil, "without the mark, its fresh time says it runs")
	local dev = ns.DEV
	ns.DEV = true
	ns.UI:Refresh()
	check(AppLight() == "App (12 running)", "a development build counts the apps running, got "..tostring(AppLight()))
	ns.DEV = false
	ns.UI:Refresh()
	check(AppLight() == "App", "a release doesn't, got "..tostring(AppLight()))
	ns.DEV = dev
	WantedAppInfo = nil
	ns.Widgets.IsDialogShown = shown
	ns.UI:Show("web")
end)()
