	local mine = ns.Store:GetChainSeq(ns.Store:GetOrigin())
	ns.Store:SkipTo(ns.Store:GetOrigin(), mine + 100, nil)
	check(ns.Store:GetChainSeq(ns.Store:GetOrigin()) == mine, "our own chain is never skipped")
