	ns.db.recentPeers["Peer One"], ns.db.recentPeers["Peer Two"], ns.db.recentPeers["Peer Three"] = clock, clock, clock
	ClearSent()
	for i = #joinedWith, 1, -1 do joinedWith[i] = nil end
	local leftBefore = #leftChannels
	inChannel[main] = nil
