	UnitIsPlayer = function(unit) return names[unit] ~= nil or origIsPlayer(unit) end
	check(ns.Ranks:ForUnit("nameplate7").r == 7 and ns.Ranks:ForUnit("nameplate8") == nil, "a unit's rank by its full name")
