-- Tooltips: W:Explain on a widget, a plain frame and a text; the (i) glyph; tips on segmented and menu items; a
-- list's empty hint behind a glyph
;(function()
	local W = ns.Widgets
	local function Tip() return _G.WantedTooltip end
	local function Hover(frame) frame._scripts.OnEnter(frame) end
	local function Leave(frame) frame._scripts.OnLeave(frame) end
	check(W.AttachTooltip == W.Explain, "AttachTooltip is Explain under its older name")
	-- A button, through the older name: its own OnEnter shows it, in the new style
	local button = W:Button(UIParent, "Go", "secondary", 80, 26)
	check(W:AttachTooltip(button, "Go", "Goes.") == button, "a widget is its own owner")
	Hover(button)
	check(Tip() and Tip():IsShown() and Tip().owner == button, "hovering an explained button shows the tooltip")
	check(Tip().title._text == "Go" and Tip().body._text == "Goes.", "with its title and body")
	check(Tip().title._textColor[1] == 1 and Tip().title._textColor[2] == 0.82, "the title in gold")
	check(Tip()._point[1] == "BOTTOM" and Tip()._point[3] == "TOP", "above the owner by default")
	Leave(button)
	check(not Tip():IsShown(), "and leaving hides it")
	Hover(button)
	button._mouseOver = true
	GameTooltip:Hide()
	check(Tip():IsShown(), "GameTooltip hidden elsewhere (a world object left, a timer) while the mouse is on the owner: ours stays")
	button._mouseOver = false
	GameTooltip:Hide()
	check(not Tip():IsShown(), "a page's own GameTooltip:Hide() as the mouse leaves hides it too")
	-- Disabled: it still explains why
	W:Explain(button, "Can't go", "Officers only.")
	check(button._motionWhileDisabled == true, "an explained button keeps its motion scripts while disabled")
	button:Disable()
	Hover(button)
	check(Tip():IsShown() and Tip().title._text == "Can't go", "a disabled button shows its tooltip")
	Leave(button)
	-- Explained again while its tooltip shows: the new text shows at once, not on the next hover
	button:Enable()
	W:Explain(button, "Roster", "Asking the leader.")
	Hover(button)
	W:Explain(button, "Roster", "Ann, Bob")
	check(Tip():IsShown() and Tip().body._text == "Ann, Bob", "explaining again while shown redraws: "..tostring(Tip().body._text))
	Leave(button)
	W:Explain(button, "Roster", "Ann, Bob, Cy")
	check(not Tip():IsShown(), "explaining again while hidden doesn't show it")
	Hover(button)
	W:Explain(button, nil)
	check(not Tip():IsShown(), "its text cleared while shown: it goes")
	Leave(button)
	-- The body as a function, called on each hover
	local calls = 0
	W:Explain(button, "Count", function() calls = calls + 1 return "Hover "..calls end)
	Hover(button) Leave(button) Hover(button)
	check(calls == 2 and Tip().body._text == "Hover 2", "a function body is called on each hover: "..calls)
	Leave(button)
	-- No body: the title alone
	W:Explain(button, "Title only")
	Hover(button)
	check(not Tip().body:IsShown(), "no body, no body line")
	Leave(button)
	-- A plain frame: a click-through Button over it carries the tooltip, so the controller reaches it
	local plain = CreateFrame("Frame", nil, UIParent)
	local entered = 0
	plain:SetScript("OnEnter", function() entered = entered + 1 end)
	local over = W:Explain(plain, "Plain", "A frame.")
	check(over ~= plain and over._kind == "Button" and over._parent == plain and over._clicks == false and over._motion == true,
		"a plain frame gets a click-through Button over it")
	check(W:Explain(plain, "Plain", "Again.") == over, "kept when explained again")
	Hover(over)
	check(entered == 1 and Tip():IsShown() and Tip().body._text == "Again.", "the frame's own OnEnter still runs, with the latest text")
	Leave(over)
	check(not Tip():IsShown(), "and leaving it hides the tooltip")
	-- A FontString: a click-through button over its text
	local holder = CreateFrame("Frame", nil, UIParent)
	local text = ns.Theme:Text(holder, "body", "Short")
	local hit = W:Explain(text, "Text", "Explained.")
	check(hit ~= text and hit._kind == "Button" and hit._parent == holder, "a text gets a button on its parent")
	check(hit._clicks == false and hit._motion == true, "which lets clicks through")
	check(W:Explain(text, "Text", "Again.") == hit, "and keeps it when explained again")
	local width = hit._w
	text:SetText("A much longer line of text")
	check(hit._w > width, "the button follows the text's width: "..width.." to "..hit._w)
	Hover(hit)
	check(Tip():IsShown() and Tip().owner == hit, "hovering the text shows its tooltip")
	Leave(hit)
	text:Hide()
	Hover(hit)
	check(not Tip():IsShown(), "a hidden text explains nothing")
	-- The (i) glyph
	local glyph = W:InfoGlyph(holder, "Rule", "How the card works.")
	check(glyph._kind == "Button" and glyph._w == 14 and glyph._h == 14, "the glyph is a 14 px button")
	check(glyph.ring._texture:find("Media\\ring$") and glyph.letter._texture:find("Media\\info%-i$"), "drawn from our own textures")
	check(glyph.ring._vertexColor[4] == 0.3 and glyph.letter._vertexColor[4] == 0.55, "faint at rest")
	Hover(glyph)
	check(glyph.ring._vertexColor[4] == 0.8 and Tip():IsShown() and Tip().title._text == "Rule", "lit and explaining on hover")
	Leave(glyph)
	check(glyph.ring._vertexColor[4] == 0.3 and not Tip():IsShown(), "back at rest after")
	check(W:InfoGlyph(holder, "Big", "x", 20)._w == 20, "a size can be given")
	-- Segmented items take a tip
	local control = W:Segmented(UIParent, { { key = "a", label = "One", tip = { "One", "The first." } }, { key = "b", label = "Two" } }, nil, 80)
	Hover(control.buttons[1])
	check(Tip():IsShown() and Tip().body._text == "The first.", "a segmented item's tip shows")
	Leave(control.buttons[1])
	Hover(control.buttons[2])
	check(not Tip():IsShown(), "an item without one shows nothing")
	-- Menu items take a tip, shown beside the menu
	W:Menu({ { text = "Locked", disabled = true, tip = { "Locked", "Ask an officer." } }, { text = "Plain", onClick = function() end } })
	local items = {}
	for _, f in ipairs(Mock.created) do
		if f._kind == "Button" and type(rawget(f, "def")) == "table" and f.def.text then items[f.def.text] = f end
	end
	Hover(items.Locked)
	check(Tip():IsShown() and Tip().body._text == "Ask an officer." and Tip()._point[1] == "BOTTOMLEFT", "a menu item's tip shows, beside it")
	Leave(items.Locked)
	Hover(items.Plain)
	check(not Tip():IsShown(), "a menu item without one shows nothing")
	W:HideMenu()
	-- A list's empty hint is a glyph after the empty text, not a line under it
	local list = W:List(UIParent, 20, 3, function() end, function() end)
	list:SetItems({}, "No bounties yet.", "Post one from the Board.")
	check(list.emptyGlyph:IsShown() and list.emptyGlyph.tooltipTitle == "No bounties yet." and list.emptyGlyph.tooltipText == "Post one from the Board.",
		"an empty list with a hint shows a glyph that explains it")
	list:SetItems({}, "Nothing.")
	check(not list.emptyGlyph:IsShown(), "no hint, no glyph")
	list:SetItems({ 1 }, "Nothing.", "Hint.")
	check(not list.emptyGlyph:IsShown(), "and none once the list has items")
end)()
-- Settings: each section's explanation behind an (i) by its header, or on the row it explains; only the BattleTag
-- line (a privacy fact before joining) and the disputed-kill pointer stay as notes
;(function()
	local function Tip(title)
		for _, f in ipairs(Mock.created) do
			if rawget(f, "tooltipTitle") == title and (not rawget(f, "explainedText") or f.explainedText._shown) then
				local on, p = f._shown, f._parent
				while on and p do on, p = p._shown, p._parent end
				if on then return type(f.tooltipText) == "function" and f.tooltipText() or f.tooltipText end
			end
		end
	end
	local function OnScreen(text)
		for _, f in ipairs(Mock.fontStrings) do
			if f._text == text then
				local on, p = f._shown, f._parent
				while on and p do on, p = p._shown, p._parent end
				if on then return true end
			end
		end
	end
	ns.UI:Show("settings")
	local tabs = {}
	for _, f in ipairs(Mock.created) do
		if type(rawget(f, "buttons")) == "table" and type(rawget(f, "Select")) == "function" then tabs[#tabs + 1] = f end
	end
	local function Tab(key)
		for _, bar in ipairs(tabs) do
			for _, b in ipairs(bar.buttons) do if b.key == key then bar:Select(key) end end
		end
	end
	Tab("alerts")
	check(Tip("Targeted warning") and Tip("Targeted warning"):find("someone off screen", 1, true), "Settings: the targeted section's rule behind its (i)")
	check(OnScreen("Still nearby for") and Tip("Still nearby for") and not OnScreen("Add your own sounds with a SharedMedia addon."), "short row labels, the rest on hover")
	Tab("sharing")
	check(Tip("What Wanted sends to chat") and Tip("Wanted community") and OnScreen("Members can see each other's BattleTag."), "the chat rule behind an (i); the BattleTag line stays on screen before joining")
	check(OnScreen("Disputed kill? Post the screenshot:") and Tip("Disputed kill"), "where to post a disputed kill's screenshot is on the link's tooltip")
	Tab("ranks")
	check(Tip("Where ranks come from") and Tip("Rank on nameplates"):find("ElvUI and Plater", 1, true), "where ranks come from behind an (i); the nameplates note on its row")
	Tab("emotes")
	check(Tip("Emote buttons") and Tip("Emote buttons"):find("after combat", 1, true), "the emote chips' styles behind an (i)")
	Tab("streaks")
	check(Tip("Announce streaks to") and Tip("Announce streaks to"):find("Never in public chat", 1, true), "what announcing a streak posts is on its row")
	Tab("look")
	check(Tip("Window theme") and Tip("Window theme"):find("felt follows", 1, true), "the theme card's default behind an (i)")
	Tab("alerts")
end)()
