;(function()
	local W, C = ns.Widgets, ns.Theme.C
	-- Segmented: 28 px cells, round ends on the outer cells only, the chosen one in the accent
	local control = W:Segmented(UIParent, { { key = "a", label = "Low" }, { key = "b", label = "Mid" }, { key = "c", label = "High" } }, nil, 80)
	local first, middle, last = control.buttons[1], control.buttons[2], control.buttons[3]
	check(control._h == 28 and first._h == 28, "segmented cells are 28 px high")
	check(#first.caps == 2 and first.caps[1]._point[1] == "LEFT" and #last.caps == 2 and last.caps[1]._point[1] == "RIGHT" and middle.caps == nil,
		"the end cells have round caps on their outer sides, the middle none")
	check(first.caps[1]._texture:find("cap%-fill$") and first.caps[2]._texture:find("cap%-ring$"), "drawn from our own cap textures")
	check(first._edges[3]._shown == false and first._edges[4]._shown ~= false, "the square edge gives way to the cap")
	control:Select("b", true)
	check(middle.label._textColor[1] == C.accent[1] and first.label._textColor[1] == 1, "the chosen cell's text is in the accent, the others white")
	local single = W:Segmented(UIParent, { { key = "only", label = "Only" } }, nil, 80)
	check(#single.buttons[1].caps == 4, "a single cell is round at both ends")
	-- Page tabs keep the underline and stay square
	local tabs = W:Tabs(UIParent, { { key = "a", label = "One" }, { key = "b", label = "Two" } }, nil, 80)
	tabs:Select("b", true)
	check(tabs.buttons[2].underline._shown and not tabs.buttons[1].underline._shown and tabs.buttons[1].caps == nil, "tabs underline the one shown, without caps")
	-- The dropdown: the value without a "v", a chevron, and a menu at least as wide with the current choice in the accent
	local picked
	local choice = W:Choice(UIParent, 200, { { key = 1, label = "First" }, { key = 2, label = "Second" } }, function(key) picked = key end)
	choice:SetChoice(2)
	check(choice._h == 28 and choice.label._text == "Second" and choice.chevron._texture:find("chevron$"), "a dropdown shows its value and our chevron")
	choice:Click()
	local menu = _G.WantedMenu
	check(menu and menu._w >= 200, "its menu is at least as wide as the field: "..tostring(menu and menu._w))
	local second
	for _, item in ipairs(menu.items) do if rawget(item, "def") and item.def.text == "Second" then second = item end end
	check(second and second.label._textColor[1] == C.accent[1] and second.rest == 0.04 and second._h == 28, "the current choice is marked, rows 28 px")
	local inSpecial = false
	for _, name in ipairs(UISpecialFrames) do if name == "WantedMenu" then inSpecial = true end end
	check(inSpecial, "Escape closes the menu")
	second:Click()
	check(picked == 2, "choosing from it calls back")
	-- The slider's value box: a typed number is kept in range and on a step, Escape puts the value back
	local got
	local slider = W:Slider(UIParent, "Size", 200, 10, 100, 5, function(v) return v.."%" end, function(v) got = v end)
	local s = slider.slider
	s.SetValue = function(self, v) self._value = v self._scripts.OnValueChanged(self, v) end
	s.GetValue = function(self) return self._value or 10 end
	slider:SetValue(50)
	check(slider.box._text == "50%" and got == nil, "SetValue shows the value in the box without calling back")
	slider.box:SetText("73")
	slider.box._scripts.OnEnterPressed(slider.box)
	check(got == 75 and slider.box._text == "75%", "a typed number snaps to the step and applies: "..tostring(got))
	slider.box:SetText("500")
	slider.box._scripts.OnEnterPressed(slider.box)
	check(got == 100, "and stays in range: "..tostring(got))
	slider.box:SetText("abc")
	slider.box._scripts.OnEscapePressed(slider.box)
	check(slider.box._text == "100%", "Escape puts the value back")
	-- The checkbox: an 18 px box, its edge brighter when checked
	local toggle = W:Toggle(UIParent, "Sound", nil)
	check(toggle.box._w == 18, "the checkbox is 18 px")
	check(toggle.box._edges[1]._color[4] == 0.05, "its edge faint unchecked")
	toggle:SetChecked(true)
	check(toggle.box._edges[1]._color[4] == 0.15 and toggle.check._shown and toggle.label._textColor[4] == 1, "brighter when checked, filled, its label white")
	-- A disabled button fades to 30% white
	local button = W:Button(UIParent, "Go", "primary", 80, 26)
	button:Disable()
	button._scripts.OnDisable(button)
	check(button.label._textColor[1] == 1 and button.label._textColor[4] == 0.3 and button._edges[1]._color[4] == 0.12,
		"a disabled button's text at 30% white, its edge at 12%")
	-- Section headers: 41% white, a line under them when given a width
	local header = W:SectionLabel(UIParent, "Alerts", 300)
	check(header._text == "ALERTS" and header._textColor[4] == 0.41 and header.rule and header.rule._w == 300, "a section header with its rule")
	check(rawget(W:SectionLabel(UIParent, "Plain"), "rule") == nil, "and none without a width")
	-- The dialog: 390 wide, its buttons side by side about its centre
	W:Dialog({ title = "Sure?", text = "It can't be undone." })
	local dialogFrame = _G.WantedDialog.frame
	check(dialogFrame._w == 390, "a dialog is 390 wide: "..tostring(dialogFrame._w))
	check(dialogFrame.cancel._point[1] == "BOTTOMRIGHT" and dialogFrame.cancel._point[3] == "BOTTOM" and dialogFrame.confirm._point[1] == "BOTTOMLEFT"
		and dialogFrame.confirm._point[3] == "BOTTOM", "with Cancel and OK either side of its centre")
	dialogFrame.cancel:Click()
	-- Fonts: Inter for Latin and Cyrillic in the font's weight, the client's fonts for Korean and Chinese
	local members
	CreateFontFamily = function(_, list) members = list return CreateFont() end
	ns.Theme:MakeFont("WantedTestFont", 12, nil, nil, "semibold")
	CreateFontFamily = nil
	local files = {}
	for _, m in ipairs(members) do files[m.alphabet] = m.file end
	check(files.roman:find("Media\\fonts\\Inter%-SemiBold%.ttf$") and files.russian == files.roman,
		"the font family: Inter SemiBold for Latin and Cyrillic: "..tostring(files.roman).." / "..tostring(files.russian))
	check(files.korean == "Fonts\\2002.TTF" and files.simplifiedchinese == "Fonts\\ARKai_T.ttf" and files.traditionalchinese == "Fonts\\blei00d.TTF",
		"and the client's fonts for Korean and Chinese")
	for _, name in ipairs({ "Inter-Medium.ttf", "Inter-SemiBold.ttf", "Inter-OFL.txt" }) do
		local f = io.open(ADDON.."Media/fonts/"..name, "rb")
		check(f, "the font ships: Media/fonts/"..name)
		if f then f:close() end
	end
end)()
-- The new widgets: switch, setting row, cog, multiselect, scroll area and step bar. Everything that carries a tooltip is a
-- Button, so the controller's smart navigation reaches it and its FocusEnter (OnEnter) shows the tip.
;(function()
	local W, C = ns.Widgets, ns.Theme.C
	local function Tip() return _G.WantedTooltip end
	local function Focus(button)
		check(button._kind == "Button", "a tooltip carrier is a Button, reachable by the controller")
		button._scripts.OnEnter(button)
		local shown = Tip():IsShown() and Tip().owner == button
		button._scripts.OnLeave(button)
		return shown
	end
	-- Switch
	local changed
	local switch = W:Switch(UIParent, function(on) changed = on end)
	check(switch._w == 40 and switch._h == 20 and not switch:GetChecked(), "a switch is 40 by 20, off")
	check(switch.knob._point[1] == "LEFT" and switch.track._color[4] == 0.65, "off: the knob at the left on a grey track")
	switch:Click()
	check(changed == true and switch:GetChecked() and switch.knob._point[1] == "RIGHT" and switch.track._color[1] == C.accent[1], "a click turns it on: knob right, accent track")
	switch:SetChecked(false)
	check(changed == true and not switch:GetChecked(), "SetChecked doesn't call back")
	W:Explain(switch, "Sound", "Beeps.")
	check(Focus(switch), "a switch explains itself under the controller")
	-- Row: label left, control 20 px from the right, shades taking turns, the help on the label
	local parent = CreateFrame("Frame", nil, UIParent)
	local control = W:Switch(parent)
	local row = W:Row(parent, 600, "Alert sounds", control, "Plays a beep.")
	local row2 = W:Row(parent, 600, "Stealth alarm", W:Switch(parent))
	check(row._h == 44 and row.control == control and control._parent == row and control._point[1] == "RIGHT" and control._point[2] == -20,
		"a row is 44 high with its control 20 px from the right")
	check(row.shade._color[4] == 0.1 and row2.shade._color[4] == 0.2, "rows under one parent take turns in shade")
	local hit = row.label.explainHit
	check(hit and hit.tooltipTitle == "Alert sounds" and hit.tooltipText == "Plays a beep.", "the row's help is on its label")
	check(Focus(hit), "and the label's tip shows under the controller")
	check(rawget(row2.label, "explainHit") == nil, "no help, no tip")
	-- Cog: left of the control, its popup built on first opening
	local built = 0
	local cog = W:Cog(row, "Alert sound", function(popup, width)
		built = built + 1
		check(width == 300, "the popup is 300 wide")
		return 120
	end)
	check(cog._point[1] == "RIGHT" and cog._point[2] == control and cog.icon._texture:find("Media\\cog$"), "the cog sits left of the control, drawn from our texture")
	check(cog.icon._vertexColor[4] == 0.4 and built == 0, "faint at rest, nothing built yet")
	cog:Click()
	check(built == 1 and cog.popup._shown and cog.popup._h == 120 and cog.popup.title._text == "ALERT SOUND", "a click builds and opens the popup")
	check(cog.icon._vertexColor[4] == 0.7, "brighter while it's open")
	cog:Click()
	check(not cog.popup._shown and built == 1, "a second click closes it, built once")
	local inSpecial = false
	for _, name in ipairs(UISpecialFrames) do if _G[name] == cog.popup then inSpecial = true end end
	check(inSpecial, "Escape closes it")
	cog:Disable()
	cog._scripts.OnDisable(cog)
	check(cog.icon._vertexColor[4] == 0.15, "fainter when disabled")
	check(Focus(cog), "and a disabled cog still explains itself")
	-- MultiSelect: the field lists what's on; the list stays open while ticking; locked options can't change
	local calls = {}
	local multi = W:MultiSelect(UIParent, 260, {
		{ key = "map", label = "World map", tip = { "World map", "Fronts on the map." } },
		{ key = "minimap", label = "Minimap", note = "tracking" },
		{ key = "bar", label = "Capture bar", locked = true },
	}, function(key, checked, selected) calls[#calls + 1] = { key, checked, selected } end, "Nowhere")
	check(multi.label._text == "Nowhere", "nothing on: the placeholder")
	multi:SetSelected({ map = true, minimap = true })
	check(multi.label._text == "World map, Minimap" and #calls == 0, "SetSelected shows the ones on, without calling back")
	multi:Click()
	check(multi.list._shown, "a click opens the list")
	local rows = multi.list.rows
	check(#rows == 3 and rows[1].check._shown and not rows[3].check._shown and rows[2].note._text == "tracking", "one row a option, ticked ones filled, notes on the right")
	check(rows[1].box._w == 16 and rows[1]._h == 28, "16 px boxes on 28 px rows")
	rows[2]:Click()
	check(#calls == 1 and calls[1][1] == "minimap" and calls[1][2] == false and multi.list._shown and multi.label._text == "World map", "unticking calls back and the list stays open")
	rows[3]:Click()
	check(#calls == 1 and rows[3]._alpha == 0.45, "a locked option can't be ticked and shows faint")
	check(multi:GetSelected().map and not multi:GetSelected().minimap, "GetSelected reads what's on")
	check(Focus(rows[1]), "an option's tip shows under the controller")
	multi:SetOptions({ { key = "a", label = "A" }, { key = "b", label = "B" } })
	multi:SetSelected({ a = true, b = true })
	check(multi.label._text == "All", "every option on: All")
	multi:Click()
	check(not multi.list._shown, "a click on the field closes the list")
	-- Scroll area: a bar only when the content is taller than the room, the wheel within it
	local scroll = W:Scroll(UIParent, 400, 200)
	scroll.SetVerticalScroll = function(self, v) self._vscroll = v end
	scroll:Fit(150)
	check(not scroll.thumb._shown, "content that fits: no bar")
	scroll:Fit(600)
	check(scroll.thumb._shown and scroll.content._w == 388, "taller content: a bar, and the content leaves room for it")
	scroll._scripts.OnMouseWheel(scroll, -1)
	check(scroll._vscroll == 44, "the wheel scrolls a row at a time: "..tostring(scroll._vscroll))
	for _ = 1, 20 do scroll._scripts.OnMouseWheel(scroll, -1) end
	check(scroll._vscroll == 400, "and stops at the end: "..tostring(scroll._vscroll))
	-- Step bar: done ticked green, the current one ringed in the accent, failed a red cross, the rest small and faint
	local went
	local bar = W:StepBar(UIParent, 600, { "Claimed", { "Witnessed", "A second hunter saw it." }, "Confirmed", "Paid" }, function(i) went = i end)
	check(bar._h == 64 and #bar.dots == 4 and #bar.lines == 3, "four dots on three lines, 64 high")
	bar:Set(3, { "2m ago", "by Thane", "waiting" })
	local d = bar.dots
	check(d[1].mark._shown and d[1].mark._texture:find("tick$") and d[1].ring._vertexColor[2] == C.green[2], "a done step is ticked green")
	check(d[3].ring._texture:find("ring%-bold$") and d[3].ring._vertexColor[1] == C.accent[1] and d[3].number._shown, "the current one ringed in the accent, numbered")
	check(d[4]._w == 14 and d[3]._w == 18, "steps to come are smaller dots")
	check(bar.lines[1]._color[2] == C.green[2] and bar.lines[3]._color[4] == 0.12, "the line is green behind done steps")
	check(d[2].sub._text == "by Thane" and d[2].tooltipTitle == "Witnessed" and d[2].tooltipText == "A second hunter saw it.\n\nby Thane", "sub-lines, and each dot's tooltip its rule and note")
	check(Focus(d[2]), "a dot explains its step under the controller")
	d[1]:Click()
	check(went == 1, "a done step goes back to it")
	went = nil
	d[4]:Click()
	check(went == nil, "a step to come doesn't")
	bar:Set(3, nil, { [2] = true })
	check(d[2].mark._texture:find("cross$") and d[2].ring._vertexColor[1] == C.red[1] and bar.lines[2]._color[4] == 0.12, "a failed step is a red ring with a cross")
	bar:Set(2, nil, { [2] = true }, { [3] = true, [4] = true })
	check(d[2].mark._texture:find("cross$") and d[3].mark._shown and d[3].mark._texture:find("tick$") and d[4]._w == 18, "a checklist: steps after the current one can be done too")
end)()
-- Settings in rows: switches for on/off, multiselects for where things show, cogs for the finer settings
;(function()
	ns.UI:Show("settings")
	local function Find(test) for _, f in ipairs(Mock.created) do if test(f) then return f end end end
	local function RowOf(label) return Find(function(f) return rawget(f, "label") and rawget(f, "control") and f.label._text == label end) end
	local nearby = RowOf("Show in each row")
	check(nearby and nearby.control.list and #nearby.control.list.rows == 13, "Nearby's 13 row items are one multiselect")
	local show = ns.db.settings.nearby
	local guild = show.guild
	nearby.control:Click()
	for _, row in ipairs(nearby.control.list.rows) do if row.option.key == "guild" then row:Click() end end
	check(show.guild == not guild, "ticking an item changes the setting")
	show.guild = guild
	local ranks = RowOf("Also show ranks in")
	check(ranks and #ranks.control.list.rows == 4, "ranks' other places are a multiselect")
	local fronts = RowOf("Show capture fronts on")
	check(fronts and #fronts.control.list.rows == 3, "capture fronts' places are a multiselect")
	local targeted = RowOf("Show a TARGETED warning")
	check(targeted and targeted.control.GetChecked and Find(function(f) return rawget(f, "icon") and rawget(f, "tooltipTitle") == "The TARGETED warning" end), "the TARGETED warning is a switch with a cog")
	local callout = RowOf("Show a callout for streaks and multi-kills")
	check(callout and Find(function(f) return rawget(f, "icon") and rawget(f, "tooltipTitle") == "Streak callout" end), "the streak callout is a switch with a cog")
	local detect = ns.db.settings.detect
	local sound = RowOf("Alert sounds")
	local was = detect.sound
	sound.control:Click()
	check(detect.sound == not was, "an on/off setting is a switch on its row")
	detect.sound = was
	ns.UI:Refresh()
	check(sound.control:GetChecked() == (was and true or false), "and follows the setting")
end)()
-- Bounties: the explanations moved off the Board, Your bounties and Your hunts into tooltips
;(function()
	local W, C = ns.Widgets, ns.Theme.C
	local function Shown(f) local on, p = f._shown, f._parent while on and p do on, p = p._shown, p._parent end return on end
	local function OnScreen(text)
		for _, fs in ipairs(Mock.fontStrings) do if type(fs._text) == "string" and fs._text:find(text, 1, true) and Shown(fs) then return fs end end
	end
	local function Tip(title)
		for _, f in ipairs(Mock.created) do if rawget(f, "tooltipTitle") == title and Shown(f) then return f end end
	end
	local function Body(f) local body = f and f.tooltipText return type(body) == "function" and body() or body end
	ns.UI:Show("board")
	check(not OnScreen("Kill the target and the claim files itself"), "the Board has no subtitle")
	check(Body(Tip("How bounties work")) == "Bounties on enemy players. Kill the target and the claim files itself; the poster pays by mail.", "the core rule is behind an (i) by Post a bounty")
	local nameBox
	for _, fs in ipairs(Mock.fontStrings) do if fs._text == "Player name" and Shown(fs) then nameBox = fs._parent end end
	check(nameBox and nameBox.tooltipText == "Target an enemy, or type the name of one you've seen.", "the name box says what to put in it")
	check(not OnScreen("Target an enemy, or type the name"), "and the form doesn't say it on screen")
	nameBox:SetText("Nobody Seenatall")
	nameBox._scripts.OnTextChanged(nameBox, true)
	local notSeen = OnScreen("Not seen yet")
