		for _, fs in ipairs(Mock.fontStrings) do
			local b = fs._parent
			if fs._text == label and b and b._shown and b._parent and b._parent._shown and rawget(b, "tooltipText") then return b end
		end
	end
	local function Says(label, text)
		local b = TipOf(label)
