	local realStop, realAfter = debugprofilestop, C_Timer.After
	local nextFrame = {}
	debugprofilestop = function() return os.clock() * 1000 * scale end
	C_Timer.After = function(_, f) nextFrame[#nextFrame + 1] = f end
