	Fire("CHAT_MSG_ADDON", "WNTD", "H:bz1:1/1:"..ns.Sync:Encode({ c = {}, k = helloKey, g = "Player-1-0B0A" }), "CHANNEL", "Busy Peer", nil, nil, nil, ns.Sync:GetInfo().channelName)
