			V:Want(Store:Get(r.id), true)
		end
		for _ = 1, 30 * #records do RunTimers() if V:Counts() and select(3, V:Counts()) == 0 then break end end
		for _ = 1, 60 do RunTimers() end
		for _, held in ipairs(taken) do
