	local dir = os.getenv("WANTED_FIXTURES")
	if dir then
		for _, name in ipairs({ "go_keys.json", "small_order_keys.json", "go_signed.json", "lua_signed.json" }) do
			local text = Read(dir.."/"..name)
			if text and name == "go_keys.json" then
