-- Poker gold: cash on the table. A seat at a gold table waits, with no chips, until its buy-in has reached the host
-- (by trade or by mail); when a player leaves, the host owes them their stack, as a line both clients keep; the lines
-- are paid by trade or by mail; a debt the host leaves two days counts against their reputation; the open debts and
-- the table under way live in the vault (character macros), so a crash loses nothing
;(function()
	local P = WantedPokerTestNS
	local Host, Client, Gold, Net, Vault, Protocol = P.PokerHost, P.PokerClient, P.PokerGold, P.PokerNet, P.PokerVault, P.PokerProtocol
	local now = 9000
	local sent = {}
	local function Sent(to, kind) for i = #sent, 1, -1 do local m = sent[i] if m.to == to and (m.tbl and m.tbl.k == kind or m.line and kind == "own") then return m end end end
	local lines = {}
	local host = Host:New({ name = "Ann-Realm", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 5, stakes = "gold", title = "Gold Den" },
		send = function(target, tbl) sent[#sent + 1] = { to = target, tbl = tbl } end, now = function() return now end,
		on = function(event, line) if event == "settle" then sent[#sent + 1] = { to = "own", line = line } lines[#lines + 1] = line end end })
	host:Receive("Ann-Realm", { k = "join", t = host.id, b = 2000 })
	host:Receive("Bob-Realm", { k = "join", t = host.id, b = 1000 })
	check(host.seats[1].stack == 2000 and host.seats[1].unpaid == nil, "the host's own seat is paid: they hold the money")
	check(host.seats[2].stack == 0 and host.seats[2].unpaid == 1000 and host.seats[2].bought == 0, "Bob's seat waits for his buy-in")
	local welcome = Sent("Bob-Realm", "welcome")
	check(welcome.tbl.st.seats[2].unpaid == 1000 and welcome.tbl.st.holding == 0, "and his state says what's due; the host holds nothing yet")
	check(select(2, host:Players()) == 1, "an unpaid seat is not dealt in")
	check(host:Paid("Bob-Realm", 400, "trade") and host.seats[2].unpaid == 1000 and host.seats[2].received == 400 and host.seats[2].stack == 0, "part of it: still waiting")
	check(host:Paid("Bob-Realm", 700, "mail") and host.seats[2].unpaid == nil and host.seats[2].stack == 1000 and host.seats[2].bought == 1000, "the rest, and a bit over: dealt in with the buy-in")
	check(#lines == 1 and lines[1].kind == "refund" and lines[1].amount == 100 and lines[1].from == "Ann-Realm" and lines[1].to == "Bob-Realm", "the 100 over is owed straight back")
	check(select(2, host:Players()) == 2 and host:Holding() == 1000, "dealt in; the host holds his 1000")
	-- A seat whose buy-in never comes is given up; part of one comes back
	host:Receive("Cat-Realm", { k = "join", t = host.id, b = 500, c = "not a class" })
	local cat = host:SeatOf("Cat-Realm")
	check(cat and host.seats[cat].class == nil, "a class that isn't one is dropped")
	host:Receive("Dan-Realm", { k = "join", t = host.id, b = 500 })
	host:Paid("Dan-Realm", 200, "trade")
	now = now + Protocol.PAY_SECONDS + 1
	host:Tick()
	check(host:SeatOf("Cat-Realm") == nil and host:SeatOf("Dan-Realm") == nil, "seats unpaid after three minutes are given up")
	check(#lines == 2 and lines[2].to == "Dan-Realm" and lines[2].amount == 200 and lines[2].kind == "refund", "Dan's 200 goes back; Cat, who paid nothing, is owed nothing")
	-- The host lets a seat in by hand: with what they say they received, within the range; a tournament entry exactly
	host:Receive("Fay-Realm", { k = "join", t = host.id, b = 1000 })
	local okAdmit, whyAdmit = host:Admit("Fay-Realm", 300)
	check(okAdmit == false and whyAdmit == "the buy-in is 4s to 20s", "less than the least buy-in: not let in: "..tostring(whyAdmit))
	check(host:Admit("Fay-Realm", 600) and host.seats[host:SeatOf("Fay-Realm")].stack == 600 and host.seats[host:SeatOf("Fay-Realm")].bought == 600 and host.seats[host:SeatOf("Fay-Realm")].unpaid == nil, "she sent 6s of the 10s she asked for: let in with 6s")
	check(host:Admit("Fay-Realm", 5) == false, "nothing due now")
	host:Receive("Fay-Realm", { k = "leave", t = host.id })
	-- A rebuy is chips once the money has come
	host.phase, host.hand, host.hs = "waiting", nil, nil
	host.seats[2].stack = 300
	host:Receive("Bob-Realm", { k = "rebuy", t = host.id, b = 700 })
	check(host.seats[2].stack == 300 and host.seats[2].rebuyDue == 700 and Sent("Bob-Realm", "state").tbl.st.seats[2].rebuyDue == 700, "a rebuy asked is chips only once paid; Bob is told what's due")
	check(host:Paid("Bob-Realm", 700, "trade") and host.seats[2].stack == 1000 and host.seats[2].bought == 1700 and host.seats[2].rebuyDue == nil, "paid: the chips are his")
	check(host:Paid("Eve-Realm", 50, "trade") == false and lines[#lines].to == "Eve-Realm" and lines[#lines].kind == "refund", "money from someone with nothing due is owed back")
	-- Leaving: the host owes the stack, never the other way round
	host.seats[2].stack = 600
	host:Receive("Bob-Realm", { k = "leave", t = host.id })
	local bobLine = Sent("Bob-Realm", "settle")
	check(bobLine and bobLine.tbl.l.from == "Ann-Realm" and bobLine.tbl.l.to == "Bob-Realm" and bobLine.tbl.l.amount == 600 and bobLine.tbl.l.kind == "cashout", "leaving with 600: the host owes Bob 600")
	check(Sent("own", "own").line.id == bobLine.tbl.l.id, "the host's own ledger gets the same line")
	host:Receive("Eve-Realm", { k = "join", t = host.id, b = 800 })
	host:Paid("Eve-Realm", 800, "trade")
	host.seats[host:SeatOf("Eve-Realm")].stack = 950
	host:Close()
	local eveLine = Sent("Eve-Realm", "settle")
	check(eveLine and eveLine.tbl.l.amount == 950 and eveLine.tbl.l.kind == "cashout" and Sent("Ann-Realm", "settle") == nil, "closing owes Eve her stack; the host has no line of their own")
	-- A chips table settles nothing
	sent = {}
	local chips = Host:New({ name = "Ann-Realm", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4 }, send = function(target, tbl) sent[#sent + 1] = { to = target, tbl = tbl } end, now = function() return now end })
	chips:Receive("Ann-Realm", { k = "join", t = chips.id, b = 2000 })
	chips:Receive("Bob-Realm", { k = "join", t = chips.id, b = 1000 })
	check(chips.seats[2].stack == 1000 and chips.seats[2].unpaid == nil, "play chips are dealt at once")
	chips.seats[2].stack = 100
	chips:Receive("Bob-Realm", { k = "leave", t = chips.id })
	check(Sent("Bob-Realm", "settle") == nil, "play chips settle nothing")

	-- A player's client takes a line only from its host and only about itself
	local taken = {}
	local player = Client:New({ name = "Cat-Realm", send = function() end, now = function() return now end, on = function(event, line) if event == "settle" then taken[#taken + 1] = line end end })
	player:Join("Ann-Realm", host.id, 500)
	player:Receive("Ann-Realm", { k = "settle", t = host.id, l = { id = host.id..":9", from = "Ann-Realm", to = "Cat-Realm", amount = 400, title = "Gold Den", kind = "cashout" } })
	check(#taken == 1 and taken[1].amount == 400 and taken[1].host == "Ann-Realm" and taken[1].title == "Gold Den" and taken[1].kind == "cashout", "the line is taken")
	player:Receive("Bob-Realm", { k = "settle", t = host.id, l = { id = "x", from = "Bob-Realm", to = "Cat-Realm", amount = 999 } })
	player:Receive("Ann-Realm", { k = "settle", t = host.id, l = { id = "y", from = "Dan-Realm", to = "Eve-Realm", amount = 5 } })
	player:Receive("Ann-Realm", { k = "settle", t = host.id, l = { id = "z", from = "Ann-Realm", to = "Cat-Realm", amount = 0.5 } })
	check(#taken == 1, "not from someone else, not about others, not a fraction of silver")

	-- The host of a gold table gone for good: the table is over and the seat claims its stack as it stood at the
	-- start of the hand; nobody takes the table over, since nobody else holds the money
	local events = {}
	local me = Net:Me()
	local gone = Client:New({ name = "Bob-Realm", send = function() end, now = function() return now end, on = function(event, ...) events[#events + 1] = { event, ... } end })
	gone:Join("Ann-Realm", "Ann-Realm#lost", 1000)
	gone.backup = { id = "Ann-Realm#lost", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, stakes = "gold" }, seats = {} }
	gone:Receive("Ann-Realm", { k = "welcome", t = "Ann-Realm#lost", st = { t = "Ann-Realm#lost", host = "Ann-Realm", e = 1, q = 1, me = 2, phase = "playing", open = true,
		cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, stakes = "gold", title = "Lost Den" }, seats = { [1] = { n = "Ann-Realm", s = 2000 }, [2] = { n = "Bob-Realm", s = 940, tot = 60, bought = 1000 } } } })
	now = now + Protocol.HOST_TIMEOUT + 1
	gone:Tick()
	local function Count(event) local n = 0 for _, e in ipairs(events) do if e[1] == event then n = n + 1 end end return n end
	check(Count("hostGone") == 1 and Count("takeover") == 0 and Count("hostLost") == 0 and not gone.left, "half a minute quiet: the host has gone quiet, nobody takes over a gold table")
	now = now + Protocol.HOST_LOST_SECONDS
	gone:Tick()
	local lost
	for _, e in ipairs(events) do if e[1] == "hostLost" then lost = e[2] end end
	check(lost and lost.claim and lost.from == "Ann-Realm" and lost.to == "Bob-Realm" and lost.amount == 1000 and lost.kind == "cashout" and lost.id == "Ann-Realm#lost:out:Bob" and gone.left and Count("left") == 1,
		"two minutes: the host is lost, the seat claims 1000 (its stack plus the hand's bets) and the table is over")
	-- A claim gives way to the host's own line for the same table and player, and never replaces one
	wipe(P.db.ledger)
	Gold:Add({ id = "X:out:Me", table = "X", title = "Lost Den", host = "Ann-Realm", at = time(), from = "Ann-Realm", to = me, amount = 1000, kind = "cashout", claim = true })
	Gold:Add({ id = "X:3", table = "X", title = "Lost Den", host = "Ann-Realm", at = time(), from = "Ann-Realm", to = me, amount = 980, kind = "cashout" })
	check(#Gold:Lines() == 1 and Gold:Lines()[1].id == "X:3", "the host's line replaces the claim")
	Gold:Add({ id = "X:out:Me", table = "X", title = "Lost Den", host = "Ann-Realm", at = time(), from = "Ann-Realm", to = me, amount = 1000, kind = "cashout", claim = true })
	check(#Gold:Lines() == 1, "a claim after the host's line is dropped")

	-- The ledger, and paying by mail
	wipe(P.db.ledger)
	Gold:Add({ id = "T1:1", table = "T1", title = "Gold Den", host = me, at = time() - 10, from = me, to = "Ann-Realm", amount = 150, kind = "cashout" })
	Gold:Add({ id = "T1:1", table = "T1", title = "Gold Den", host = me, at = time() - 10, from = me, to = "Ann-Realm", amount = 150, kind = "cashout" })
	Gold:Add({ id = "T1:2", table = "T1", title = "Gold Den", host = "Bob-Realm", at = time() - 3 * 86400, from = "Bob-Realm", to = me, amount = 60, kind = "cashout" })
	Gold:Add({ id = "T1:3", table = "T1", title = "Gold Den", host = me, at = time() - 20, from = me, to = "Bob-Realm", amount = 40, kind = "prize" })
	Gold:Add({ id = "T1:in:Bob:1", table = "T1", title = "Gold Den", host = me, at = time() - 30, from = "Bob-Realm", to = me, amount = 50000, kind = "buyin", paid = time() - 30, paidHow = "trade" })
	check(#Gold:Lines() == 4 and Gold:Owing() == 190, "lines are kept once; a receipt is no debt; you owe 190 in all")
	local function Line(id) for _, l in ipairs(Gold:Lines()) do if l.id == id then return l end end end
	check(Gold:IsOverdue(Line("T1:2")) and not Gold:IsOverdue(Line("T1:1")) and not Gold:IsOverdue(Line("T1:in:Bob:1")), "a debt unpaid two days is overdue; a receipt never is")
	local realMoney, realSendMoney, realCount, realHeader = GetMoney, GetSendMailMoney, GetInboxNumItems, GetInboxHeaderInfo
	GetMoney = function() return 500 * 10000 end -- 500g: 5,000,000 copper, the chips of a gold table
	check(Gold:CanBuyIn(4999810) == true and not Gold:CanBuyIn(4999811), "a buy-in is covered by the money in the bags less what you owe: 500g - 190c")
	MailFrame._shown = true
	check(Gold:Prefill(Line("T1:1")) and SendMailSubjectEditBox:GetText() == "Wanted poker T1:1" and SendMailNameEditBox:GetText() == "Ann-Realm", "Pay fills the mail in")
	check(not Gold:Prefill(Line("T1:2")), "not a debt of yours: nothing filled in")
	local function SendHook(recipient, subject, copper)
		GetSendMailMoney = function() return copper end
		for _, f in ipairs(globalHooks.SendMail or {}) do f(recipient, subject, "") end
	end
	SendHook("Ann-Realm", "Wanted poker T1:1", 150)
	Fire("MAIL_SEND_SUCCESS")
	check(Line("T1:1").paid and Line("T1:1").paidHow == "mail", "sent with the amount: paid")
	SendHook("Bob-Realm", "gg", 39)
	Fire("MAIL_SEND_SUCCESS")
	check(not Line("T1:3").paid, "a mail with less than the line isn't the payment")
	SendHook("Bob-Realm", "gg", 40)
	Fire("MAIL_SEND_SUCCESS")
	check(Line("T1:3").paid, "a hand-written mail with the amount pays the oldest line to that player")
	check(Gold:Owing() == 0, "nothing owed")
	-- Receiving: a mail from the debtor with the amount
	GetInboxNumItems = function() return 1 end
	GetInboxHeaderInfo = function() return nil, nil, "Bob-Realm", "Wanted poker T1:2", 60 end
	Fire("MAIL_INBOX_UPDATE")
	check(Line("T1:2").paid, "the creditor's client marks the line paid when the mail arrives")
	-- Reputation: a debt left unpaid counts against its debtor; one paid counts for them; a claim counts for nothing
	Gold:Add({ id = "T2:1", table = "T2", title = "Gold Den", host = "Stiff-Realm", at = time() - 3 * 86400, from = "Stiff-Realm", to = me, amount = 50000, kind = "cashout" })
	Gold:Add({ id = "T3:out:Me", table = "T3", title = "Gold Den", host = "Vague-Realm", at = time() - 3 * 86400, from = "Vague-Realm", to = me, amount = 500, kind = "cashout", claim = true })
	local tally = ns.Reputation:GetTally("Stiff-Realm")
	check(tally.unpaid == 1 and tally.points < 0, "a poker debt two days unpaid counts like a bounty left unpaid")
	check(ns.Reputation:GetTally("Bob-Realm").paid >= 1, "a poker debt paid counts like a bounty paid")
	check(ns.Reputation:GetTally("Vague-Realm").unpaid == 0, "a claim this client made counts for nothing until the host's own line comes")
	GetMoney, GetSendMailMoney, GetInboxNumItems, GetInboxHeaderInfo = realMoney, realSendMoney, realCount, realHeader

	-- The page's Settlement view (the paid debts dropped first: the list shows four rows)
	for i = #P.db.ledger, 1, -1 do if P.db.ledger[i].paid and P.db.ledger[i].kind ~= "buyin" then tremove(P.db.ledger, i) end end
	local function OnScreen(text) for _, fs in ipairs(Mock.fontStrings) do if fs._shown ~= false and tostring(fs._text):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):find(text, 1, true) then return true end end return false end
	ns.UI:Show("poker")
	local switch
	for _, f in ipairs(Mock.created) do local l = rawget(f, "label") if type(l) == "table" and l._text == "Settlement (2)" then switch = f end end
	check(switch, "the Settlement view counts what's open")
	switch._scripts.OnClick(switch)
	check(OnScreen("Stiff owes you 5g") and OnScreen("OVERDUE") and OnScreen("Paid") and OnScreen("Received 5g from Bob") and OnScreen("host dropped"), "the lines show in gold and silver: the overdue one marked, the receipt, the claim")
	-- Amounts typed and shown
	check(Protocol:Money(25000, "gold") == "2g 50s" and Protocol:Money(100000, "gold") == "10g" and Protocol:Money(5, "gold") == "5c" and Protocol:Money(10005, "gold") == "1g 5c" and Protocol:Money(0, "gold") == "0c" and Protocol:Money(250, "chips") == "250", "copper shows as gold, silver and copper")
	check(Protocol:ParseAmount("2g 50s", "gold") == 25000 and Protocol:ParseAmount("10g", "gold") == 100000 and Protocol:ParseAmount("75s", "gold") == 7500 and Protocol:ParseAmount("2.5", "gold") == 25000 and Protocol:ParseAmount("5c", "gold") == 5
		and Protocol:ParseAmount("1g 5c", "gold") == 10005 and Protocol:ParseAmount("2g50s", "gold") == 25000 and Protocol:ParseAmount("abc", "gold") == nil and Protocol:ParseAmount("400", "chips") == 400 and Protocol:ParseAmount("4.5", "chips") == nil, "typed money is read")

	-- Trades: a buy-in traded to the host seats the player; the host's trade pays a line; the inbox takes a mailed buy-in
	wipe(P.db.ledger)
	local money = 1000 * 10000
	local realGetMoney, realUnitName, realGetUnitName = GetMoney, UnitName, GetUnitName
	GetMoney = function() return money end
	local tradeWith = "Bob-Realm"
	GetUnitName = function(unit, full) if unit == "NPC" then return tradeWith end return realGetUnitName(unit, full) end
	local give, get = 0, 0
	GetPlayerTradeMoney = function() return give end
	GetTargetTradeMoney = function() return get end
	local function Trade(name, giveCopper, getCopper)
		tradeWith, give, get = name, giveCopper, getCopper
		Fire("TRADE_SHOW")
		Fire("TRADE_ACCEPT_UPDATE", 1, 1)
		money = money - giveCopper + getCopper
		Fire("TRADE_CLOSED")
	end
	check(Net:HostTable({ sb = 5, bb = 10, buyMin = 200, buyMax = 1000, maxSeats = 4, stakes = "gold", title = "Trade Den" }, 1000), "a gold table through Net")
	local netHost = Net:HostedTable()
	-- Someone says hello on the channel: the host repeats the table's ad for them a moment later, not at its next
	-- 45-second repeat, and not again for another hello within 15 seconds
	do
		-- (Sent here is this block's own helper for the table's whispers: the ad is read off the channel sends)
		local function Ads() local ids, n = {}, 0 for _, m in ipairs(addonSent) do local id = m.chatType == "CHANNEL" and m.text:match("^T:(%w+):") if id and not ids[id] then ids[id] = true n = n + 1 end end return n end
		ClearSent()
		Fire("CHAT_MSG_ADDON", "WNTD", Message("H", { c = {} }), "CHANNEL", "Late Arrival", nil, nil, nil, ns.Sync:GetInfo().channelName)
		check(Ads() == 0, "the ad for a late arrival waits a moment")
		RunTimers()
		check(Ads() == 1, "then the open table is advertised again for them, got "..Ads())
		Fire("CHAT_MSG_ADDON", "WNTD", Message("H", { c = {} }), "CHANNEL", "Later Arrival", nil, nil, nil, ns.Sync:GetInfo().channelName)
		RunTimers()
		check(Ads() == 1, "not again for a hello right after")
	end
	local function From(name, tbl) tbl.t, tbl.v = netHost.id, "0.1.0-dev" Fire("CHAT_MSG_ADDON", "WNTD", "P:zt"..math.random(1000, 9999)..":1/1:"..ns.Sync:Encode(tbl), "WHISPER", name) end
	From("Bob-Realm", { k = "join", b = 500 })
	check(netHost.seats[2] and netHost.seats[2].unpaid == 500, "Bob's seat waits for 5g")
	P.PokerTable:Show()
	check(P.PokerTable:GetParts().seats[1].admit:IsShown() and P.PokerTable:GetParts().seats[1].admit.label._text == "Let in", "the host sees Let in on Bob's waiting seat")
	check(P.PokerTable:GetParts().seats[1].trust._text ~= nil and P.PokerTable:GetParts().seats[0].trust._text ~= nil, "each seat shows the player's trust to pay beside the name")
	Trade("Bob-Realm", 0, 500)
	check(netHost.seats[2].unpaid == nil and netHost.seats[2].stack == 500, "Bob trades the host 5g: seated with his chips")
	local receipt
	for _, l in ipairs(Gold:Lines()) do if l.kind == "buyin" and l.from == "Bob-Realm" then receipt = l end end
	check(receipt and receipt.paid and receipt.paidHow == "trade" and receipt.amount == 500 and receipt.to == me, "the host's ledger has the receipt")
	From("Bob-Realm", { k = "leave" })
	local owed
	for _, l in ipairs(Gold:Lines()) do if l.kind == "cashout" and l.to == "Bob-Realm" and not l.paid then owed = l end end
	check(owed and owed.amount == 500 and owed.from == me, "Bob leaves: the host owes him his 5g")
	Trade("Bob-Realm", 500, 0)
	check(owed.paid and owed.paidHow == "trade", "the host trades it to him: paid")
	From("Cal-Realm", { k = "join", b = 300 })
	GetInboxNumItems = function() return 1 end
	GetInboxHeaderInfo = function() return nil, nil, "Cal-Realm", "Wanted poker buy-in "..netHost.id, 300 end
	Fire("MAIL_INBOX_UPDATE")
	Fire("MAIL_INBOX_UPDATE")
	local _, cal = netHost:SeatOf("Cal-Realm")
	check(cal and cal.stack == 300 and cal.unpaid == nil and netHost:Holding() == 300, "Cal's mailed buy-in seats her, counted once")
	GetInboxNumItems, GetInboxHeaderInfo = realCount, realHeader
	-- The vault follows the table; closing sums up what the host owes
	clock = clock + 2
	RunTimers()
	local kept = Vault:Load()
	check(kept and kept.table and kept.table.id == netHost.id and #kept.table.seats == 1 and kept.table.seats[1].n == "Cal-Realm" and kept.table.seats[1].s == 300, "the vault holds the table: Cal's seat and stack")
	local from = #printed
	Net:Leave()
	local summary = false
	for i = from + 1, #printed do summary = summary or (printed[i]:find("table closed", 1, true) and printed[i]:find("Cal 3s", 1, true)) ~= nil end
	check(summary, "closing says who's owed what")
	clock = clock + 2
	RunTimers()
	kept = Vault:Load()
	check(kept and kept.table == nil and #kept.lines == 1 and kept.lines[1].to == "Cal-Realm", "the vault keeps the open debt and no table")
	GetMoney, UnitName, GetUnitName, GetPlayerTradeMoney, GetTargetTradeMoney = realGetMoney, realUnitName, realGetUnitName, nil, nil

	-- Lines asked for and answered between players: a host sends the debts it owes the asker; an answer is taken only
	-- for lines the sender owes this character
	addonSent = {}
	Fire("CHAT_MSG_ADDON", "WNTD", "P:zl1:1/1:"..ns.Sync:Encode({ k = "lines", v = "0.1.0-dev" }), "WHISPER", "Cal-Realm")
	local answer
	for _, m in ipairs(addonSent) do if m.target == "Cal-Realm" and m.text:find("^P:") then answer = ns.Sync:Decode(m.text:match("^P:%w+:%d+/%d+:(.*)$")) end end
	check(answer and answer.k == "lines" and #answer.l == 1 and answer.l[1].amount == 300 and answer.l[1].to == "Cal-Realm", "Cal asks: the host answers with the 3g it owes her")
	Fire("CHAT_MSG_ADDON", "WNTD", "P:zl2:1/1:"..ns.Sync:Encode({ k = "lines", v = "0.1.0-dev", l = { { id = "A:9", table = "A", from = "Ann-Realm", to = me, amount = 55, kind = "cashout", at = time() }, { id = "A:10", table = "A", from = "Zed-Realm", to = me, amount = 66, kind = "cashout", at = time() } } }), "WHISPER", "Ann-Realm")
	check(Line("A:9") and Line("A:9").amount == 55 and Line("A:10") == nil, "Ann's answer: her own debt is taken, one she claims for Zed is not")

	-- The vault: data kept across a crash in macros, in chunks, written out of combat
	local saved = {}
	local function Roundtrip(data)
		Vault:Save(data)
		clock = clock + 2
		RunTimers()
		return Vault:Load()
	end
	local long = "" -- hashes: text that doesn't compress away
	for i = 1, 10 do long = long..ns.Crypto:Hex(ns.Crypto:SHA512("chunk"..i)) end
	local back = Roundtrip({ v = 1, lines = { { id = "L:1", amount = 7 } }, text = long })
	check(back and back.lines[1].id == "L:1" and back.text == long and #mockMacros >= 2, "a kilobyte of data comes back whole from several macros: "..#mockMacros)
	back = Roundtrip({ small = true })
	check(back and back.small == true and mockMacros[2].body == "", "smaller data empties the chunks it no longer needs")
	local realLockdown = InCombatLockdown
	InCombatLockdown = function() return true end
	Vault:Save({ later = true })
	clock = clock + 2
	RunTimers()
	check(Vault:Load().small == true, "nothing is written in combat")
	InCombatLockdown = realLockdown
	Fire("PLAYER_REGEN_ENABLED")
	check(Vault:Load().later == true, "it's written once the fight is over")
	-- A crash with a table under way: at the next login every seat is owed what it had
	Roundtrip({ v = 1, lines = { { id = "V:1", table = "V", title = "Old Den", host = me, from = me, to = "Zed-Realm", amount = 70, kind = "cashout", at = time() } },
		table = { id = "Me#crash", title = "Crashed Den", kind = "cash", seats = { { n = "Bob-Realm", s = 650, b = 500 }, { n = "Cat-Realm", s = 0, b = 0, u = 300, r = 100 }, { n = "Dan-Realm", s = 0, b = 200 } } } })
	wipe(P.db.ledger)
	from = #printed
	Gold:Recover()
	check(Line("V:1") and Line("V:1").amount == 70, "a debt the saved variables lost is back from the vault")
	check(Line("Me#crash:out:Bob") and Line("Me#crash:out:Bob").amount == 650 and Line("Me#crash:out:Bob").kind == "cashout" and Line("Me#crash:out:Bob").from == me, "Bob is owed the 650 he had")
	check(Line("Me#crash:out:Cat") and Line("Me#crash:out:Cat").amount == 100 and Line("Me#crash:out:Cat").kind == "refund", "Cat, never dealt in, is owed the 100 she'd paid")
	check(Line("Me#crash:out:Dan") == nil, "Dan, busted, is owed nothing")
	local told = false
	for i = from + 1, #printed do told = told or printed[i]:find("ended with the last session", 1, true) ~= nil end
	check(told, "and the host is told")
	clock = clock + 2
	RunTimers()
	kept = Vault:Load()
	check(kept.table == nil and #kept.lines == 3, "the vault now holds the three debts and no table")
	wipe(P.db.ledger)
	Gold:Persist()
	clock = clock + 2
	RunTimers()
	check(Vault:Load() == nil, "nothing owed, nothing kept")
end)()

-- Poker tournaments and passwords: a locked table asks for its password; a tournament registers, starts on the host's
-- word, raises the blinds by the clock, folds a player sitting out at once, bleeds an absent one, places the
-- eliminated, and ends with standings and the prizes settled; cancelled, it settles nothing
;(function()
	local P = WantedPokerTestNS
	local Host, Client, Protocol = P.PokerHost, P.PokerClient, P.PokerProtocol
	local nodes, queue, events = {}, {}, {}
	local now = 20000
	local function Now() return now end
	local function SendFrom(from) return function(target, tbl) queue[#queue + 1] = { from = from, to = target, text = ns.Sync:Encode(tbl), k = tbl.k } end end
	local function Flush()
		local guard = 0
		while #queue > 0 do
			guard = guard + 1 assert(guard < 20000, "the table never settles")
			local m = tremove(queue, 1)
			local node = nodes[m.to]
			if node then
				local tbl = ns.Sync:Decode(m.text)
				if node.host and Protocol.TO_HOST[tbl.k] then node.host:Receive(m.from, tbl) end
				if node.player and Protocol.TO_PLAYER[tbl.k] then node.player:Receive(m.from, tbl) end
			end
		end
	end
	local function Tick(seconds)
		for _ = 1, seconds do
			now = now + 1
			for _, node in pairs(nodes) do if node.host then node.host:Tick() end if node.player then node.player:Tick() end end
			Flush()
		end
	end
	local function Node(name)
		events[name] = {}
		local node = { name = name }
		node.player = Client:New({ name = name, send = SendFrom(name), now = Now, on = function(event, ...) tinsert(events[name], { event, ... }) end })
		nodes[name] = node
		return node
	end
	local function Last(name, event) for i = #events[name], 1, -1 do if events[name][i][1] == event then return events[name][i] end end end
	local ads, settled = {}, {}

	-- A password
	local ann = Node("Ann-Realm")
	ann.host = Host:New({ name = "Ann-Realm", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4 }, send = SendFrom("Ann-Realm"), ad = function(ad) ads[#ads + 1] = ad end, now = Now, password = "Saloon" })
	local locked = ann.host
	ann.player:Join("Ann-Realm", locked.id, 1000, "saloon")
	local bob = Node("Bob-Realm")
	bob.player:Join("Ann-Realm", locked.id, 1000)
	Flush()
	check(ann.player.seat == 1 and bob.player.seat == nil and Last("Bob-Realm", "refused")[2] == "wrong password", "no password, no seat")
	bob.player:Join("Ann-Realm", locked.id, 1000, "opensesame")
	Flush()
	check(bob.player.seat == nil, "a wrong password, no seat")
	bob.player:Join("Ann-Realm", locked.id, 1000, " SALOON ")
	Flush()
	check(bob.player.seat == 2, "the password, whatever its case and spaces, seats you")
	locked:Advertise()
	check(ads[#ads].p == 1, "the ad says the table is locked")
	for _, st in ipairs({ ann.player.state, bob.player.state }) do check(st.cfg.password == nil, "the password never travels in the state") end
	locked:Close()
	Flush()
	ann.player:Leave() bob.player:Leave()

	-- A tournament: gold entry 2g, stacks of 1000, a level a minute
	nodes = {}
	ann, bob = Node("Ann-Realm"), Node("Bob-Realm")
	local cat, dan, eve = Node("Cat-Realm"), Node("Dan-Realm"), Node("Eve-Realm")
	ann.host = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 200, startStack = 1000, levelMinutes = 1, maxSeats = 4, stakes = "gold", title = "Dead Man's Open", lateLevels = 0 },
		send = SendFrom("Ann-Realm"), ad = function(ad) ads[#ads + 1] = ad end, now = Now, on = function(event, line) if event == "settle" then settled[#settled + 1] = line end end })
	local t = ann.host
	check(t.cfg.sb == 10 and t.cfg.bb == 20 and t.cfg.buyMin == 200 and t.cfg.buyMax == 200, "a tournament's blinds start at the schedule's first level; the entry is the one buy-in")
	ann.player:Join("Ann-Realm", t.id, 200)
	bob.player:Join("Ann-Realm", t.id, 200)
	cat.player:Join("Ann-Realm", t.id, 200)
	dan.player:Join("Ann-Realm", t.id, 100)
	Flush()
	check(ann.player.seat == 1 and bob.player.seat == 2 and cat.player.seat == 3 and dan.player.seat == nil and Last("Dan-Realm", "refused")[2] == "the entry is 2s", "three enter at the entry; a wrong amount is refused")
	check(t.seats[1].stack == 1000 and t.seats[2].stack == 0 and t.seats[2].unpaid == 200 and bob.player.state.seats[2].unpaid == 200, "the host's own seat is paid; the others wait for their entry to arrive, and are told")
	check(t:Paid("Bob-Realm", 200, "trade") and t:Paid("Cat-Realm", 200, "mail"), "the entries arrive by trade and by mail")
	Flush()
	check(t.seats[2].stack == 1000 and t.seats[2].bought == 200 and t.seats[2].unpaid == nil and t.seats[3].stack == 1000, "everyone starts with the same chips, having paid the entry")
	Tick(3)
	check(t.phase == "waiting" and t.hand == nil and not ann.player.state.started, "no hand before the host starts it")
	t:Receive("Bob-Realm", { k = "rebuy", t = t.id, b = 500 })
	check(t.seats[2].stack == 1000, "no rebuys in a tournament")
	local ok = t:Start()
	Flush()
	check(ok and ann.player.state.started and ads[#ads].k == "t" and ads[#ads].on == 1, "started: everyone's state and the ad say so")
	eve.player:Join("Ann-Realm", t.id, 200)
	Flush()
	check(eve.player.seat == nil and Last("Eve-Realm", "refused")[2] == "the tournament has started", "nobody enters after the start")
	Tick(1)
	check(t.phase == "playing" and t.hand.bb == 20 and ann.player.state.level == 1, "the first hand at level 1")
	local function Turn() for _, n in pairs(nodes) do if n.player.seat == t.hand.toAct then return n end end end
	local function Play(action, amount) local n = Turn() check(n and n.player:Act(action, amount), "the player to act can "..action) Flush() end
	local function PlayOut(watch)
		local guard = 0
		while t.phase == "playing" do
			guard = guard + 1 assert(guard < 100, "the hand never ends")
			local n = Turn()
			if watch then check(n ~= watch, watch.name.." is never left to act: the host folds them at once") end
			if n and nodes[n.name] then Play(n.player.state.hand.legal.check and "check" or "fold") else Tick(31) end
		end
	end
	PlayOut()
	-- The clock: a minute on, the next hand is at level 2
	Tick(61)
	Tick(Protocol.SHOWDOWN_SECONDS + 1)
	while t.phase ~= "playing" do Tick(1) end
	check(t.hand.bb == 30 and ann.player.state.level == 2 and ann.player.state.levelBlinds[2] == 30, "a minute later the blinds are 15/30: "..tostring(t.hand.bb))
	-- Sitting out: dealt in, folded at once on their turn, blinds and all
	cat.player:SitOut()
	Flush()
	PlayOut()
	Tick(Protocol.SHOWDOWN_SECONDS + 1)
	while t.phase ~= "playing" do Tick(1) end
	check(t.hand.seats[3] ~= nil, "a player sitting out is still dealt in")
	PlayOut(cat)
	check(t.seats[3].away == 0, "and never times out")
	cat.player:Back()
	Flush()
	-- An absent client: a big blind a hand leaves their stack
	nodes["Bob-Realm"] = nil
	local bobStack = t.seats[2].stack
	Tick(Protocol.SHOWDOWN_SECONDS + 1)
	Tick(Protocol.COMMIT_SECONDS + Protocol.REVEAL_SECONDS + 2)
	check(t.seats[2].stack == bobStack - 30 and not (t.hand and t.hand.seats[2]), "Bob's client answers nothing: a big blind gone, dealt out this hand")
	nodes["Bob-Realm"] = bob
	PlayOut()
	-- Leaving forfeits: Bob goes out third, his entry stays with the host; then Cat takes every chip and is owed the prize
	bob.player:Leave()
	Flush()
	check(t.entrants["Bob-Realm"].place == 3 and t.entrants["Bob-Realm"].left, "leaving a tournament takes the current place")
	check(Last("Bob-Realm", "settle") == nil, "and forfeits the entry: nothing comes back")
	t.phase, t.hand, t.hs = "waiting", nil, nil
	t.seats[1].stack, t.seats[3].stack = 0, 3000
	t:Eliminate(1)
	t:Finish()
	Flush()
	check(t.phase == "finished", "one player with every chip: finished")
	local st = ann.player.state
	check(st.standings and st.standings[1].name == "Cat-Realm" and st.standings[1].place == 1 and st.standings[1].prize == 600 and st.standings[2].name == "Ann-Realm" and st.standings[3].name == "Bob-Realm", "standings with the winner's prize, the whole pool with three entered")
	check(#settled == 1 and settled[1].to == "Cat-Realm" and settled[1].amount == 600 and settled[1].kind == "prize" and ads[#ads].c == 1, "one line: the host owes Cat the prize; the ad says the table is done")
	check(Last("Cat-Realm", "settle")[2].amount == 600, "Cat is told")
	check(Protocol:TournamentMinutes(1500, 8, 10) == 90 and Protocol:TournamentMinutes(1500, 2, 5) == 25 and Protocol:TournamentMinutes(1500, 8, 10, true) == 81, "a tournament's length: the level where the field holds 25 big blinds, times the level: "..Protocol:TournamentMinutes(1500, 8, 10)..", "..Protocol:TournamentMinutes(1500, 2, 5))
	check(Protocol:AboutMinutes(90) == "about 1 h 30 min" and Protocol:AboutMinutes(25) == "about 25 min" and Protocol:AboutMinutes(120) == "about 2 h" and Protocol:AboutMinutes(81) == "about 1 h 20 min", "lengths in words")
	check(Protocol:Prizes(1000, 5)[1] == 650 and Protocol:Prizes(1000, 5)[2] == 350 and Protocol:Prizes(1001, 7)[1] == 501 and Protocol:Prizes(1001, 7)[3] == 200, "prizes split 65/35 from five, 50/30/20 from seven, the rounding to first")
	-- Cancelled: nothing settled
	settled = {}
	nodes = {}
	ann, bob = Node("Ann-Realm"), Node("Bob-Realm")
	ann.host = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 200, startStack = 1000, levelMinutes = 5, maxSeats = 4, stakes = "gold" },
		send = SendFrom("Ann-Realm"), now = Now, on = function(event, line) if event == "settle" then settled[#settled + 1] = line end end })
	ann.player:Join("Ann-Realm", ann.host.id, 200) bob.player:Join("Ann-Realm", ann.host.id, 200)
	Flush()
	ann.host:Paid("Bob-Realm", 200, "trade")
	ann.host:Start()
	Tick(2)
	ann.host:Close()
	Flush()
	check(#settled == 1 and settled[1].kind == "refund" and settled[1].amount == 200 and settled[1].to == "Bob-Realm" and bob.player.state.phase == "closed", "a tournament cancelled gives every entry back")
	-- A busted player's place, two in one hand by their stacks at the start of it
	local h = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 5, maxSeats = 4 }, send = function() end, now = Now })
	h:Receive("Ann-Realm", { k = "join", t = h.id, b = 0 }) h:Receive("Bob-Realm", { k = "join", t = h.id, b = 0 }) h:Receive("Cat-Realm", { k = "join", t = h.id, b = 0 }) h:Receive("Dan-Realm", { k = "join", t = h.id, b = 0 })
	h:Start()
	h.seats[2].stack, h.seats[3].stack = 40, 60
	h.hs = { key = "1.1", setup = { seats = { [2] = { stack = 40 }, [3] = { stack = 60 } } }, commits = {}, secrets = {}, deckHash = "x" }
	local function S(stack) return { stack = stack, hole = { 1, 2 }, bet = 0, total = 0 } end
	h.hand = { seats = { [1] = S(1900), [2] = S(0), [3] = S(0), [4] = S(1000) }, results = { payouts = {}, shown = {}, pots = {} }, log = {}, board = {}, street = "done" }
	h:Showdown()
	check(h.entrants["Bob-Realm"].place == 4 and h.entrants["Cat-Realm"].place == 3, "two out in one hand: the shorter stack at the start places lower")
end)()

-- A split pot at a silver table divides in silver: 15s between two is 8s and 7s, the odd silver to the first winner
-- left of the button, never 7s 50c each
;(function()
	local P = WantedPokerTestNS
	local Engine = P.PokerEngine
	local function C(rank, suit) return Engine:Card(rank, suit) end
	local function Seat(hole, total, folded) return { stack = 0, hole = hole, bet = 0, total = total, folded = folded, allin = false } end
	local function Hand(coin)
		return { seats = { [1] = Seat({ C(14, 1), C(13, 1) }, 500, false), [2] = Seat({ C(2, 2), C(3, 2) }, 500, true), [3] = Seat({ C(14, 3), C(13, 3) }, 500, false) },
			order = { 1, 2, 3 }, button = 1, sb = 100, bb = 200, ante = 0, coin = coin, board = { C(2, 4), C(7, 1), C(9, 4), C(11, 2), C(4, 3) }, log = {}, acted = {}, barred = {}, currentBet = 0, lastRaiseSize = 0, street = "river" }
	end
	local h = Hand(100)
	Engine.Settle(h)
	local pays = h.results.payouts
	check(h.results.pots[1].amount == 1500 and #h.results.pots[1].winners == 2, "ace-king against ace-king on a dry board: a 15s pot split two ways")
	check((pays[1] == 700 and pays[3] == 800) or (pays[1] == 800 and pays[3] == 700), ("in silver: 8s and 7s, got %s and %s"):format(tostring(pays[1]), tostring(pays[3])))
	h = Hand(1)
	Engine.Settle(h)
	pays = h.results.payouts
	check(pays[1] == 750 and pays[3] == 750, "at a copper table 7s 50c each, as before")
	local plain = Engine:NewHand({ seats = { [1] = { stack = 1000 }, [2] = { stack = 1000 } }, button = 1, sb = 10, bb = 20, deck = (function() local d = {} for s = 1, 4 do for r = 2, 14 do d[#d + 1] = C(r, s) end end return d end)() })
	check(plain.coin == 1, "a hand made without a coin is in copper (chips)")
end)()

-- The host kicks a player: they stand up, their stack is owed to them at a gold table, and their client is told why
;(function()
	local P = WantedPokerTestNS
	local Host = P.PokerHost
	local sent, lines = {}, {}
	local h = Host:New({ name = "Ann-Realm", cfg = { sb = 100, bb = 200, buyMin = 1000, buyMax = 100000, maxSeats = 4, stakes = "gold" },
		send = function(target, tbl) sent[#sent + 1] = { to = target, tbl = tbl } end, now = function() return 60000 end,
		on = function(event, line) if event == "settle" then lines[#lines + 1] = line end end })
	h:Receive("Ann-Realm", { k = "join", t = h.id, b = 2000 }) h:Receive("Bob-Realm", { k = "join", t = h.id, b = 1000 })
	h:Paid("Bob-Realm", 1000, "trade")
	check(h:SeatOf("Bob-Realm") == 2 and h.seats[2].stack == 1000, "Bob is dealt in with 10s")
	check(not h:Kick("Ann-Realm") and h:SeatOf("Ann-Realm") == 1, "the host can't kick their own seat")
	check(not h:Kick("Cat-Realm"), "nor someone who isn't there")
	check(h:Kick("Bob-Realm") and h:SeatOf("Bob-Realm") == nil, "Bob is kicked: his seat is empty")
	local told
	for _, m in ipairs(sent) do if m.to == "Bob-Realm" and m.tbl.k == "refuse" then told = m.tbl end end
	check(told and told.why:find("removed you", 1, true), "Bob's client is told why: "..tostring(told and told.why))
	check(#lines == 1 and lines[1].to == "Bob-Realm" and lines[1].amount == 1000 and lines[1].kind == "cashout", "his 10s are owed to him, a settlement line like anyone leaving")
end)()

-- A silver table (blinds in whole silver) takes no copper: the host refuses a buy-in or rebuy with copper in it and
-- rounds a bet or raise up to the silver whatever a client sends
;(function()
	local P = WantedPokerTestNS
	local Host, Engine, Protocol = P.PokerHost, P.PokerEngine, P.PokerProtocol
	check(Protocol:Coin({ sb = 100, bb = 200, stakes = "gold" }) == 100 and Protocol:Coin({ sb = 10000, bb = 20000, stakes = "gold" }) == 10000 and Protocol:Coin({ sb = 150, bb = 300, stakes = "gold" }) == 1 and Protocol:Coin({ sb = 100, bb = 200, stakes = "chips" }) == 1, "the table's coin: silver, gold, copper, and a chips table")
	check(Protocol:RoundUp(1050, { sb = 100, bb = 200, stakes = "gold" }) == 1100 and Protocol:RoundUp(1000, { sb = 100, bb = 200, stakes = "gold" }) == 1000, "rounding up to the silver")
	local h = Host:New({ name = "Ann-Realm", cfg = { sb = 100, bb = 200, buyMin = 1000, buyMax = 100000, maxSeats = 4, stakes = "gold" }, send = function() end, now = function() return 50000 end })
	h:Receive("Ann-Realm", { k = "join", t = h.id, b = 1050 })
	check(h:SeatOf("Ann-Realm") == nil, "a buy-in with copper is refused at a silver table")
	h:Receive("Ann-Realm", { k = "join", t = h.id, b = 1000 }) h:Receive("Bob-Realm", { k = "join", t = h.id, b = 1000 })
	check(h:SeatOf("Ann-Realm") == 1 and h:SeatOf("Bob-Realm") == 2, "whole silver sits down")
	h:Receive("Ann-Realm", { k = "rebuy", t = h.id, b = 550 })
	check(h.seats[1].stack == 1000, "a rebuy with copper is ignored")
	h:Receive("Ann-Realm", { k = "rebuy", t = h.id, b = 500 })
	check(h.seats[1].stack == 1500, "a whole-silver rebuy goes in")
	local deck = {}
	for suit = 1, 4 do for rank = 2, 14 do deck[#deck + 1] = Engine:Card(rank, suit) end end
	h.phase, h.hs, h.seq = "playing", { key = "k" }, 0
	h.hand = Engine:NewHand({ seats = { [1] = { stack = 1500 }, [2] = { stack = 1000 } }, button = 1, sb = 100, bb = 200, deck = deck })
	Engine:Start(h.hand)
	local actor = h.hand.toAct
	h:OnAct(actor, { h = "k", q = 0, a = "raise", m = 520 })
	check(h.hand.seats[actor].bet == 600, "a raise to 5s 20c from a client goes in as 6s: "..tostring(h.hand.seats[actor].bet))
end)()

-- Poker UI, tournaments: the form switches to a tournament's fields, hosting registers, the window says so, the
-- host starts it once a second player has entered by whisper, and the level shows
;(function()
	local P = WantedPokerTestNS
	local Net, TableUI = P.PokerNet, P.PokerTable
	local function OnScreen(text) for _, fs in ipairs(Mock.fontStrings) do if fs._shown ~= false and tostring(fs._text):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):find(text, 1, true) then return true end end return false end
	local function Button(label) for _, f in ipairs(Mock.created) do local l = rawget(f, "label") if type(l) == "table" and l._text == label and f._scripts.OnClick and f:IsShown() then return f end end end
	ns.UI:Show("poker")
	P.PokerPage:GoToStep(1)
	local switch = Button("Tournament")
	check(switch, "the form offers a tournament")
	switch._scripts.OnClick(switch)
	P.PokerPage:GoToStep(2)
	check(OnScreen("Levels every") and Button("Next"), "a tournament's fields: the stack and the levels")
	P.PokerPage:GoToStep(4)
	check(Button("Host table") and OnScreen("Tournament  ·  for chips") and OnScreen("Free") and OnScreen("1500  ·  levels every"), "the review names the tournament, a row a choice")
	local gameTip
	for _, f in ipairs(Mock.created) do
		if rawget(f, "tooltipTitle") == "Tournament" and rawget(f, "explainedText") and f.explainedText._shown then gameTip = f.tooltipText end
	end
	check(gameTip and gameTip:find("plays until one player has them all", 1, true) and gameTip:find("Free entry; the chips are play money", 1, true),
		"the tournament's rules and its free entry are the Game row's tooltip")
	Button("Host table")._scripts.OnClick(Button("Host table"))
	local host = Net:HostedTable()
	check(host and host.cfg.kind == "tournament" and host.cfg.entry == 0 and host.seats[1].stack == 1500, "a free chips tournament, stacks of 1500")
	check(TableUI:IsShown() and OnScreen("Registering: 1 of 6"), "the window says it's registering")
	local regTip
	for _, f in ipairs(Mock.created) do
		if rawget(f, "tooltipTitle") == "Registering: 1 of 6" then regTip = f.tooltipText end
	end
	check(regTip and regTip:find("The host starts the tournament.", 1, true), "who starts it is on hover")
	local parts = TableUI:GetParts()
	check(parts.start:IsShown(), "the host has a Start button")
	local id = host.id
	local n = 0
	local function FromBob(tbl)
		tbl.t, tbl.v = id, "0.1.0-dev"
		n = n + 1
		Fire("CHAT_MSG_ADDON", "WNTD", "P:tb"..n..":1/1:"..ns.Sync:Encode(tbl), "WHISPER", "Bob-Realm")
	end
	FromBob({ k = "join", b = 0 })
	check(host.seats[2] and host.seats[2].name == "Bob-Realm" and OnScreen("Registering: 2 of 6"), "Bob enters")
	parts.start._scripts.OnClick(parts.start)
	check(host.startedAt and Net:State().started, "started from the window")
	clock = clock + 1
	host:Tick()
	check(host.phase == "seeding" and OnScreen("Level 1") and OnScreen("10/20"), "the level and blinds show once under way")
	parts.leave._scripts.OnClick(parts.leave)
	ConfirmDialog()
	check(Net:HostedTable() == nil, "cancelled")
end)()
-- Poker bots: a practice table's computer players (Poker/Bots.lua) read their cards like a rule player; at a table
-- they join, shuffle, act and buy back in through the same messages as anyone, run by the host's own client; a
-- tournament against them plays to the end
;(function()
	local P = WantedPokerTestNS
	local Host, Bots, Protocol, Engine = P.PokerHost, P.PokerBots, P.PokerProtocol, P.PokerEngine
	local function Card(rank, suit) return Engine:Card(rank, suit) end
	local function Near(a, b) return math.abs(a - b) < 0.001 end
	-- Hole cards before the flop (Chen): aces 20 of 20, ace-king suited 12, jack-ten suited 9, a pair of fives 5, seven-deuce nothing
	check(Bots:Preflop(Card(14, 4), Card(14, 3)) == 1, "a pair of aces is the best start")
	check(Near(Bots:Preflop(Card(14, 4), Card(13, 4)), 0.6) and Near(Bots:Preflop(Card(11, 1), Card(10, 1)), 0.45), "suited high cards rate well: "..Bots:Preflop(Card(14, 4), Card(13, 4))..", "..Bots:Preflop(Card(11, 1), Card(10, 1)))
	check(Near(Bots:Preflop(Card(5, 1), Card(5, 2)), 0.25) and Bots:Preflop(Card(7, 1), Card(2, 2)) == 0, "a small pair is middling, seven-deuce is nothing")
	-- After the flop: top pair, the board's pair, nothing, a flush draw with two cards to come
	check(Near(Bots:Strength({ Card(14, 4), Card(13, 4) }, { Card(14, 3), Card(7, 2), Card(2, 1) }), 0.55), "top pair")
	check(Near(Bots:Strength({ Card(9, 1), Card(8, 2) }, { Card(13, 3), Card(13, 2), Card(2, 1), Card(5, 4), Card(3, 4) }), 0.12), "the board's pair is worth little")
	check(Near(Bots:Strength({ Card(7, 1), Card(2, 2) }, { Card(14, 3), Card(13, 2), Card(12, 1) }), 0.1), "nothing")
	local draw = Bots:Strength({ Card(9, 4), Card(8, 4) }, { Card(2, 4), Card(11, 4), Card(4, 2) })
	check(draw > 0.35 and draw < 0.45, "a flush draw on the flop is worth a call: "..draw)
	check(Bots:Strength({ Card(14, 4), Card(14, 3) }, { Card(14, 2), Card(14, 1), Card(2, 1), Card(3, 1), Card(4, 1) }) > 0.95, "four aces")
	-- Decisions, with the dice fixed
	local steady = Bots.STYLES[1]
	local function Rng(v) return function() return v end end
	local function State(o)
		return { cfg = { bb = 20, kind = "cash" }, seats = { [1] = { s = o.stack or 1000, hole = o.hole }, [2] = { s = 1000 } },
			hand = { key = "1.1", stage = "play", street = o.street, board = o.board or {}, pot = o.pot or 30, cur = o.cur or 20, legal = o.legal, log = {}, toAct = 1 } }
	end
	local aces = { Card(14, 4), Card(14, 3) }
	local trash = { Card(7, 1), Card(2, 2) }
	local action, amount = Bots:Decide(State({ hole = aces, street = "preflop", legal = { fold = true, call = 10, minRaise = 40, maxRaise = 1010 } }), 1, steady, Rng(0.5))
	check(action == "raise" and amount == 52, "aces raise before the flop, the size a little varied: "..action.." "..tostring(amount))
	action = Bots:Decide(State({ hole = trash, street = "preflop", pot = 300, cur = 200, legal = { fold = true, call = 200 } }), 1, steady, Rng(0.5))
	check(action == "fold", "seven-deuce folds to a raise: "..action)
	-- At a silver game a bot's raise is whole silver too: 2.6 x 2s = 5s 20c becomes 6s
	local silver = State({ hole = aces, street = "preflop", cur = 200, stack = 100000, legal = { fold = true, call = 100, minRaise = 400, maxRaise = 100100 } })
	silver.cfg = { sb = 100, bb = 200, stakes = "gold", kind = "cash" }
	action, amount = Bots:Decide(silver, 1, steady, Rng(0.5))
	check(action == "raise" and amount == 600, "a bot raises in whole silver at a silver game: "..action.." "..tostring(amount))
	action = Bots:Decide(State({ hole = trash, street = "flop", board = { Card(14, 3), Card(13, 2), Card(12, 1) }, legal = { fold = true, check = true, minBet = 20, maxBet = 1000 } }), 1, steady, Rng(0.5))
	check(action == "check", "nothing checks when it's free: "..action)
	action, amount = Bots:Decide(State({ hole = trash, street = "flop", board = { Card(14, 3), Card(13, 2), Card(12, 1) }, legal = { fold = true, check = true, minBet = 20, maxBet = 1000 } }), 1, steady, Rng(0))
	check(action == "bet" and amount == 20, "and bluffs now and then: "..action.." "..tostring(amount))
	action = Bots:Decide(State({ hole = { Card(14, 4), Card(13, 4) }, street = "flop", board = { Card(14, 3), Card(7, 2), Card(2, 1) }, pot = 150, cur = 50, legal = { fold = true, call = 50, minRaise = 150, maxRaise = 1000 } }), 1, steady, Rng(0.5))
	check(action == "call", "top pair calls a bet: "..action)
	action = Bots:Decide(State({ hole = aces, stack = 100, street = "preflop", legal = { fold = true, call = 10, minRaise = 40, maxRaise = 110 } }), 1, steady, Rng(0.5))
	check(action == "allin", "short with a hand goes all in: "..action)
	-- Bluffs: a second barrel follows a bluff from the street before more often than a fresh bluff starts; a lone bet
	-- is raised with nothing now and then, once a hand
	local board = { Card(14, 3), Card(13, 2), Card(12, 1), Card(4, 4) }
	local free = { fold = true, check = true, minBet = 20, maxBet = 1000 }
	local act2, _, bluff = Bots:Decide(State({ hole = trash, street = "turn", board = board, legal = free }), 1, steady, Rng(0.2), { key = "1.1", bluffStreet = "flop" })
	check(act2 == "bet" and bluff == true, "having bluffed the flop, the turn is fired again at a 20% roll: "..act2)
	act2 = Bots:Decide(State({ hole = trash, street = "turn", board = board, legal = free }), 1, steady, Rng(0.2), { key = "1.1" })
	check(act2 == "check", "without a bluff behind it the same roll checks: "..act2)
	local facing = { fold = true, call = 50, minRaise = 150, maxRaise = 1000 }
	act2, _, bluff = Bots:Decide(State({ hole = trash, street = "flop", board = { Card(14, 3), Card(13, 2), Card(12, 1) }, pot = 150, cur = 50, legal = facing }), 1, steady, Rng(0.05), { key = "1.1" })
	check(act2 == "raise" and bluff == true, "a lone bet is raised with nothing at a 5% roll: "..act2)
	act2 = Bots:Decide(State({ hole = trash, street = "flop", board = { Card(14, 3), Card(13, 2), Card(12, 1) }, pot = 150, cur = 50, legal = facing }), 1, steady, Rng(0.05), { key = "1.1", bluffRaised = true })
	check(act2 == "fold", "but only once a hand: "..act2)

	-- Settings: a practice table is chips only, keeps a seat for the host
	check(Protocol:Settings({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, bots = 3 }).bots == 3, "bots in the settings")
	check(Protocol:Settings({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, bots = 4 }) == nil, "the host keeps a seat")
	check(Protocol:Settings({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, bots = 2, stakes = "gold" }) == nil, "no gold against bots")
	check(Protocol:Settings({ sb = 100, bb = 200, buyMin = 4000, buyMax = 20000, maxSeats = 4, bots = 2, stakes = "play" }).stakes == "play", "play money against bots")
	check(Protocol:Settings({ sb = 100, bb = 200, buyMin = 4000, buyMax = 20000, maxSeats = 4, stakes = "play" }) == nil, "play money is for practice tables only")
	check(Protocol:Money(25000, "play") == "2g 50s" and Protocol:ParseAmount("2g 50s", "play") == 25000, "play money reads and shows like gold")
	check(Protocol:Settings({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000 }).bots == 0, "none by default")

	-- A cash table of four bots (the host's seat a bot too, so the table runs itself) delivered without a network,
	-- the way Net does it; a bot's dice are its own, so the run is the same every time
	math.randomseed(7)
	local now = 30000
	local function Now() return now end
	local bots, host = {}, nil
	local function Lcg(seed) local x = seed return function() x = (x * 1103515245 + 12345) % 2147483648 return x / 2147483648 end end
	local function ToBot(target, tbl) if bots[target] then bots[target]:Receive("Host", ns.Sync:Decode(ns.Sync:Encode(tbl))) end end
	host = Host:New({ name = "Host", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, bots = 3, turnSeconds = 20 }, send = ToBot, now = Now })
	check(host and host.cfg.bots == 3, "a practice table opens")
	local names = { "Host", Bots.NAMES[1], Bots.NAMES[2], Bots.NAMES[3] }
	for i, name in ipairs(names) do
		local bot = Bots:New({ name = name, style = Bots.STYLES[(i - 1) % #Bots.STYLES + 1], now = Now, rng = Lcg(i), send = function(_, tbl) host:Receive(name, ns.Sync:Decode(ns.Sync:Encode(tbl))) return true end })
		bots[name] = bot
		bot:Join("Host", host.id, 2000)
	end
	check(#host:Seated() == 4 and host.seats[2].name == Bots.NAMES[1] and host.seats[2].stack == 2000, "the bots sit with the table's top buy-in")
	local function Tick(seconds)
		for _ = 1, seconds do
			now = now + 1
			host:Tick()
			for _, bot in pairs(bots) do bot:Tick() end
		end
	end
	Tick(2)
	check(host.phase == "playing", "the bots shuffled and the hand is dealt: "..host.phase)
	local toAct = host.hand.toAct
	local thinker = bots[host.seats[toAct].name]
	check(thinker.turnKey and thinker.actAt and thinker.actAt > now - 1 and thinker.actAt <= now + Protocol.BOT_THINK_MAX, "a bot takes a moment over its turn: "..tostring(thinker.actAt and thinker.actAt - now))
	Tick(Protocol.BOT_THINK_MAX)
	check(host.hand.street == "done" or host.hand.toAct ~= toAct or host.phase ~= "playing", "and acts within its time")
	Tick(600)
	check(host.handNo >= 8, "hands are played one after another: "..host.handNo.." in ten minutes")
	local stacks, bought, timeouts = 0, 0, 0
	for _, p in pairs(host.seats) do stacks = stacks + p.stack bought = bought + p.bought timeouts = timeouts + p.away end
	check(stacks == bought, "no chip is lost or made: "..stacks.." of "..bought)
	check(timeouts == 0, "no bot ever times out")
	local verified = 0
	for _, bot in pairs(bots) do for _, a in pairs(bot.player.audits) do if a.ok then verified = verified + 1 end end end
	check(verified >= host.handNo * 2, "the bots verify the deals like players: "..verified)
	-- A bot that busts at a cash table buys back in
	local poor
	for seat, p in pairs(host.seats) do if seat ~= 1 then poor = poor or seat end end
	host.seats[poor].stack = 0
	host.seats[poor].out = "busted"
	host.phase, host.hand, host.hs = "waiting", nil, nil
	host.nextHandAt = now + 60
	host:Bump()
	host:Broadcast()
	Tick(5)
	check(host.seats[poor].stack == 2000 and host.seats[poor].out == false, "a busted bot buys back in: "..host.seats[poor].stack)

	-- A tournament against bots runs to the end: one of them, or the host, holds every chip
	bots = {}
	local tourney = Host:New({ name = "Host", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 1, maxSeats = 4, bots = 3, turnSeconds = 20 }, send = ToBot, now = Now })
	host = tourney
	for i, name in ipairs(names) do
		local bot = Bots:New({ name = name, style = Bots.STYLES[(i - 1) % #Bots.STYLES + 1], now = Now, rng = Lcg(10 + i), send = function(_, tbl) host:Receive(name, ns.Sync:Decode(ns.Sync:Encode(tbl))) return true end })
		bots[name] = bot
		bot:Join("Host", host.id, 0)
	end
	check(host:Start(), "the tournament starts with four entered")
	local seconds = 0
	while host.phase ~= "finished" and seconds < 3 * 3600 do
		Tick(10)
		seconds = seconds + 10
	end
	check(host.phase == "finished", "the tournament ends on its own: "..host.phase.." after "..seconds.."s, "..host.handNo.." hands")
	local standings = host:Standings()
	local places = {}
	for _, row in ipairs(standings) do places[#places + 1] = row.place end
	sort(places)
	check(#places == 4 and places[1] == 1 and places[4] == 4, "every entrant has a place: "..table.concat(places, ","))
	for _, row in ipairs(standings) do check(not row.left, "no bot walked out") end
end)()

-- Poker in instances: the game's chat messaging lockdown doesn't hold a plugin's whispers back (they go to players at
-- the table), a refusal says why, and while the game refuses them the table's clocks stop on both sides
;(function()
	local P = WantedPokerTestNS
	local Host, Client, Protocol, Net, TableUI = P.PokerHost, P.PokerClient, P.PokerProtocol, P.PokerNet, P.PokerTable
	local function Sent(target) local n = 0 for _, m in ipairs(addonSent) do if m.chatType == "WHISPER" and m.target == target then n = n + 1 end end return n end
	addonSent = {}
	C_ChatInfo.InChatMessagingLockdown = function() return true end
	ns.Sync:Greet("Locked Pal", "Other Realm")
	check(Sent("Locked Pal") == 0, "Wanted's own whispers wait out the lockdown")
	check(ns.Sync:SendPlugin(Protocol.TAG, { k = "sync", t = "x" }, "Seat-Realm") == true and Sent("Seat-Realm") == 1, "a table whisper goes during the lockdown")
	lockdownNext = 1
	local ok, why = ns.Sync:SendPlugin(Protocol.TAG, { k = "sync", t = "x" }, "Seat-Realm")
	check(ok == false and why == "lockdown", "one the game refuses says so: "..tostring(why))
	C_ChatInfo.InChatMessagingLockdown = nil
	lockdownNext = nil

	-- The host's clocks stop while the game refuses its messages; the player doesn't give the host up for gone
	local now = 40000
	local function Now() return now end
	local blocked = false
	local function Blocked() return blocked end
	local nodes, queue = {}, {}
	local refused = {} -- name -> true: the game refuses this one's messages (returned false, never delivered)
	local function SendFrom(from) return function(target, tbl) queue[#queue + 1] = { from = from, to = target, text = ns.Sync:Encode(tbl) } return not (blocked or refused[from]) end end
	local function Flush()
		while #queue > 0 do
			local m = tremove(queue, 1)
			local node = nodes[m.to]
			if node and not blocked and not refused[m.from] then
				local tbl = ns.Sync:Decode(m.text)
				if node.host and Protocol.TO_HOST[tbl.k] then node.host:Receive(m.from, tbl) end
				if node.player and Protocol.TO_PLAYER[tbl.k] then node.player:Receive(m.from, tbl) end
			end
		end
	end
	local events = {}
	local function Node(name)
		local node = { name = name }
		node.player = Client:New({ name = name, send = SendFrom(name), now = Now, blocked = Blocked, on = function(event) events[#events + 1] = name..":"..event end })
		nodes[name] = node
		return node
	end
	local function Tick(seconds) for _ = 1, seconds do now = now + 1 for _, node in pairs(nodes) do if node.host then node.host:Tick() end node.player:Tick() end Flush() end end
	local ann, bob = Node("Ann-Realm"), Node("Bob-Realm")
	ann.host = Host:New({ name = "Ann-Realm", cfg = { sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4, turnSeconds = 20 }, send = SendFrom("Ann-Realm"), now = Now, blocked = Blocked })
	local host = ann.host
	ann.player:Join("Ann-Realm", host.id, 1000)
	bob.player:Join("Ann-Realm", host.id, 1000)
	Flush()
	Tick(2)
	check(host.phase == "playing", "a hand under way: "..host.phase)
	local toAct, deadline, seq = host.hand.toAct, host.hs.deadline, host.seq
	blocked = true
	Tick(45)
	check(host.phase == "playing" and host.hand.toAct == toAct and host.seats[toAct].away == 0, "nobody times out while the game refuses the table's messages")
	check(host.hs.deadline == deadline + 45, "the turn clock stood still: "..(host.hs.deadline - deadline))
	check(bob.player.state.q == seq, "Bob heard nothing new")
	local gone = false
	for _, e in ipairs(events) do if e == "Bob-Realm:hostGone" then gone = true end end
	check(not gone, "and didn't give the host up for gone")
	blocked = false
	Tick(1)
	check(bob.player.state.q > seq and bob.player.state.hand.left >= 17, "through again: everyone gets the table with its clock where it stopped: "..tostring(bob.player.state.hand.left))
	Tick(20)
	check(host.hand.toAct ~= toAct or host.hand.street == "done" or host.phase ~= "playing", "then the turn runs out as usual")
	-- A commitment the game refused goes again with the host's next state
	host.phase, host.hand, host.hs, host.nextHandAt = "waiting", nil, nil, now
	refused["Bob-Realm"] = true
	Tick(1)
	check(host.phase == "seeding" and host.hs.commits[1] and not host.hs.commits[2], "a hand is called: Ann's commitment is in, Bob's was refused")
	refused["Bob-Realm"] = nil
	host:SendState("Bob-Realm", "state")
	Flush()
	check(host.hs.commits[2], "Bob commits again on the next state")

	-- Through Net and the window: a refused whisper to a seated player marks the table as waiting, and the status says so
	local function OnScreen(text) for _, fs in ipairs(Mock.fontStrings) do if fs._shown ~= false and tostring(fs._text):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):find(text, 1, true) then return true end end return false end
	check(Net:HostTable({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 4 }, 1000), "a table through Net")
	local netHost = Net:HostedTable()
	local payload = ns.Sync:Encode({ k = "join", b = 1000, t = netHost.id, v = "0.1.0-dev" })
	Fire("CHAT_MSG_ADDON", "WNTD", "P:zq1:1/1:"..payload, "WHISPER", "Cal-Realm")
	check(netHost.seats[2] and netHost.seats[2].name == "Cal-Realm", "Cal is seated by whisper")
	TableUI:Show()
	lockdownNext = 10
	netHost:Beat()
	check(Net:Blocked(), "the game refused the beat to Cal: the table is blocked")
	local pausedTip
	for _, f in ipairs(Mock.created) do
		if rawget(f, "tooltipTitle") == "Paused: table messages blocked here" then pausedTip = f.tooltipText end
	end
	check(OnScreen("Paused: table messages blocked here") and pausedTip and pausedTip:find("boss fight or a PvP match", 1, true), "the window says so, and why on hover")
	lockdownNext = nil
	clock = clock + 1
	netHost:Beat()
	check(not Net:Blocked(), "a whisper through again: not blocked")
	-- The probe: a table whisper to ourselves, reported when it comes back
	addonSent = {}
	local from = #printed
	Net:Probe()
	local probe
	for _, m in ipairs(addonSent) do if m.chatType == "WHISPER" and m.target == ns.Store:GetOrigin() and m.text:find("^P:") then probe = m.text end end
	check(probe, "the probe whispers a table message to ourselves")
	Fire("CHAT_MSG_ADDON", "WNTD", probe, "WHISPER", ns.Store:GetOrigin())
	local said = false
	for i = from + 1, #printed do said = said or printed[i]:find("came back", 1, true) ~= nil end
	check(said, "and says when it comes back")
	Net:Leave()
	check(Net:HostedTable() == nil, "closed")
end)()

-- Poker UI, practice: Practice among the stakes fills the other seats with bots, advertises nothing and plays
;(function()
	local P = WantedPokerTestNS
	local Net, TableUI, Bots = P.PokerNet, P.PokerTable, P.PokerBots
	local function OnScreen(text) for _, fs in ipairs(Mock.fontStrings) do if fs._shown ~= false and tostring(fs._text):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", ""):find(text, 1, true) then return true end end return false end
	local function Button(label) for _, f in ipairs(Mock.created) do local l = rawget(f, "label") if type(l) == "table" and l._text == label and f._scripts.OnClick and f:IsShown() then return f end end end
	ns.UI:Show("poker")
	P.PokerPage:GoToStep(4)
	-- The tooltip of what's on screen with that title: it and every frame it sits in shown
	local function Tip(title)
		for _, f in ipairs(Mock.created) do
			if rawget(f, "tooltipTitle") == title and (not rawget(f, "explainedText") or f.explainedText._shown) then
				local on, p = f._shown, f._parent
				while on and p do on, p = p._shown, p._parent end
				if on then return f.tooltipText end
			end
		end
	end
	check(OnScreen("Players and money") and (OnScreen("Cash game  ·") or OnScreen("Tournament  ·")) and OnScreen("Who sees it") and Tip("The deal"),
		"the form, with the review of the table being set up and the deal behind an (i)")
	check(not OnScreen("THE DEAL:") and not OnScreen("SEATS "), "no numbered paragraphs (they numbered the seats line wrongly)")
	check(Tip("The deal"):find("the deck is shuffled from all of them", 1, true), "the (i) explains the deal")
	-- The step bar: on Review, the three before ticked with the choices made under them; a done step goes back to it
	local stepDots = {}
	for _, f in ipairs(Mock.created) do
		local caption = rawget(f, "caption")
		if f._kind == "Button" and caption and f._parent and f._parent._shown and f._parent._parent and f._parent._parent._shown then stepDots[caption._text] = f end
	end
	check(stepDots.Game and stepDots.Game.mark._shown and stepDots.Table.mark._shown and stepDots.Review.ring._texture:find("ring%-bold$"), "on Review, the steps before are ticked")
	check((stepDots.Game.sub._text == "Cash game" or stepDots.Game.sub._text == "Tournament") and stepDots.Table.sub._text:find("^%d+ seats, %d+ s$"),
		"with the choices made under them: "..stepDots.Game.sub._text..", "..stepDots.Table.sub._text)
	check(not OnScreen("STEP 4 OF 4") and not OnScreen("  >  Review"), "no step title or footer dots")
	stepDots.Game:Click()
	check(OnScreen("Cash game") and stepDots.Game.ring._texture:find("ring%-bold$") and stepDots.Review._w == 14, "a done step is a click back to it")
	P.PokerPage:GoToStep(2)
	local practice = Button("Practice")
	check(practice, "Practice among the stakes")
	WantedPokerDB.host.kind = "cash"
	WantedPokerDB.host.seats = 3
	practice._scripts.OnClick(practice)
	check(Tip("Practice") and Tip("Practice"):find("Computer players fill the other seats", 1, true), "Practice explains itself on hover")
	P.PokerPage:GoToStep(4)
	check(OnScreen("Cash game  ·  practice, play money") and OnScreen("You and 2 computer players") and Tip("Cash game"):find("Play money: the other seats are computer players", 1, true),
		"picking Practice rewrites the review, and the Game row's tooltip says what play money is")
	check(not OnScreen("You hold the money") and not OnScreen("Your client deals"), "no gold lines at a practice table")
	-- A gold cash game: the host's two must-see lines
	WantedPokerDB.host.stakes = "gold"
	P.PokerPage:GoToStep(2)
	local goldButton = Button("Gold")
	goldButton._scripts.OnClick(goldButton)
	P.PokerPage:GoToStep(4)
	check(OnScreen("Cash game  ·  for gold") and OnScreen("You hold the money: you owe each player their stack when they leave (Settlement).")
		and OnScreen("Your client deals: play for gold only with people you trust.") and Tip("Cash on the table"):find("goes to you first", 1, true),
		"a gold game: the money rules on hover, the host's debt and the deal's trust on screen")
	P.PokerPage:GoToStep(2)
	practice._scripts.OnClick(practice)
	WantedPokerDB.host.seats = 3
	WantedPokerDB.host.stakes = "practice"
	P.PokerPage:GoToStep(4)
	addonSent = {}
	TableUI:Log("a line from the last table")
	P.PokerPage:GoToStep(4)
	local go = Button("Host table")
	go._scripts.OnClick(go)
	local host = Net:HostedTable()
	local stale = false
	for _, line in ipairs(TableUI:GetParts().lines or {}) do stale = stale or line == "a line from the last table" end
	check(not stale, "a new table starts with an empty log")
	check(host and host.cfg.bots == 2 and host.cfg.stakes == "play" and host.cfg.sb == 100 and host.cfg.bb == 200 and host.seats[2].stack == 20000 and #host:Seated() == 3, "hosting a practice table on play money at 1s/2s seats two bots with 2g each: "..tostring(host and host.cfg.stakes)..", "..tostring(host and host.seats[2] and host.seats[2].stack))
	local botsSeen = 0
	for _ in pairs(Net:Bots()) do botsSeen = botsSeen + 1 end
	local named = false
	for _, name in ipairs(Bots.NAMES) do named = named or OnScreen(name) end
	check(botsSeen == 2 and named, "the bots are at the table, by name")
	local ads = 0
	for _, m in ipairs(addonSent) do if m.text:find("^T:") then ads = ads + 1 end end
	check(ads == 0, "a practice table is not advertised")
	for _ = 1, 30 do
		clock = clock + 1
		host:Tick()
		for _, bot in pairs(Net:Bots()) do bot:Tick() end
	end
	check(host.handNo >= 1 and (host.phase == "playing" or host.phase == "showdown" or host.phase == "seeding" or host.phase == "waiting"), "hands are dealt against the bots: "..host.handNo..", "..host.phase)
	Net:Leave()
	if Net:HostedTable() then
		check(host.closing == true, "a hand under way: the practice table closes after it")
		for _ = 1, 600 do
			if not Net:HostedTable() then break end
			clock = clock + 1
			host:Tick()
			for _, bot in pairs(Net:Bots()) do bot:Tick() end
		end
	end
	check(Net:HostedTable() == nil and next(Net:Bots()) == nil, "closing clears the bots")
	WantedPokerDB.host.stakes = "chips"
end)()

-- Poker tournaments, late entry and antes: entrants sit down with the starting stack while late entry is open, places
-- follow the order players went out however many entered after them, and antes come in from level four when on
;(function()
	local P = WantedPokerTestNS
	local Host, Protocol = P.PokerHost, P.PokerProtocol
	local now = 50000
	local function Now() return now end
	local sent, ads = {}, {}
	local function Refused(name) for i = #sent, 1, -1 do if sent[i].to == name and sent[i].tbl.k == "refuse" then return sent[i].tbl.why end end end
	check(Protocol:Settings({ kind = "tournament", entry = 0 }).lateLevels == Protocol.DEFAULT_LATE_LEVELS and Protocol:Settings({ kind = "tournament", entry = 0 }).antes == false, "by default late entry stays open to level 2 and there are no antes")
	check(Protocol:Settings({ sb = 1, bb = 2, buyMin = 40, buyMax = 200, antes = true, lateLevels = 3 }).antes == false, "a cash game has neither")
	check(Protocol:Settings({ kind = "tournament", entry = 0, lateLevels = 99 }) == nil, "late entry closes within the schedule")
	local t = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 1, maxSeats = 6, lateLevels = 2, antes = true },
		send = function(to, tbl) sent[#sent + 1] = { to = to, tbl = tbl } end, ad = function(ad) ads[#ads + 1] = ad end, now = Now })
	for _, n in ipairs({ "Ann-Realm", "Bob-Realm", "Cat-Realm" }) do t:Receive(n, { k = "join", t = t.id, b = 0 }) end
	check(t:StateFor("Ann-Realm").lateLevels == 2 and not t:StateFor("Ann-Realm").lateOpen, "registering: the state says late entry stays open to level 2")
	t:Start()
	t:Receive("Dan-Realm", { k = "join", t = t.id, b = 0 })
	local danSeat = t:SeatOf("Dan-Realm")
	check(danSeat and t.seats[danSeat].stack == 1000 and t.entrants["Dan-Realm"] and t:StateFor("Dan-Realm").lateOpen, "a late entrant at level 1 sits with the starting stack")
	t:Advertise()
	check(ads[#ads].on == 1 and ads[#ads].la == 1 and ads[#ads].lv == 1 and ads[#ads].an == 1, "the ad: under way, late entry open at level 1, antes")
	now = now + 61
	t:Receive("Eve-Realm", { k = "join", t = t.id, b = 0 })
	check(t:SeatOf("Eve-Realm") ~= nil, "still open at level 2")
	now = now + 60
	t:Receive("Fay-Realm", { k = "join", t = t.id, b = 0 })
	check(t:SeatOf("Fay-Realm") == nil and Refused("Fay-Realm") == "late entry has closed", "closed at level 3: "..tostring(Refused("Fay-Realm")))
	t:Advertise()
	check(ads[#ads].on == 1 and ads[#ads].la == nil and ads[#ads].lv == 3, "the ad: under way, late entry closed")
	-- Antes: none before level 4, a tenth of the big blind from it; none when off
	check(t:Ante() == 0 and t:StateFor("Ann-Realm").ante == 0, "no ante at level 3")
	now = now + 60
	check(t:Level() == 4 and t:Ante() == 10 and t:StateFor("Ann-Realm").ante == 10, "level 4, blinds 50/100: an ante of 10")
	local quiet = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 1, maxSeats = 6 }, send = function() end, now = Now })
	quiet:Receive("Ann-Realm", { k = "join", t = quiet.id, b = 0 }) quiet:Receive("Bob-Realm", { k = "join", t = quiet.id, b = 0 })
	quiet:Start()
	now = now + 600
	check(quiet:Level() >= 4 and quiet:Ante() == 0, "antes off: none at any level")
	-- Places by the order out: the first out finishes last, however many enter after
	local p = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 60, maxSeats = 6, lateLevels = 6 }, send = function() end, now = Now })
	for _, n in ipairs({ "Ann-Realm", "Bob-Realm", "Cat-Realm" }) do p:Receive(n, { k = "join", t = p.id, b = 0 }) end
	p:Start()
	p:Eliminate(2)
	check(p.entrants["Bob-Realm"].place == 3, "Bob out first of three: third")
	p:Receive("Dan-Realm", { k = "join", t = p.id, b = 0 })
	check(p.entrants["Bob-Realm"].place == 4 and p.seats[2].place == 4, "Dan enters late: Bob is fourth of four now")
	p:Eliminate(3)
	p:Receive("Dan-Realm", { k = "leave", t = p.id })
	check(p.entrants["Cat-Realm"].place == 3 and p.entrants["Dan-Realm"].place == 2 and p.entrants["Dan-Realm"].left, "Cat third, Dan (who left) second")
	p:Finish()
	local standings = p:Standings()
	check(standings[1].name == "Ann-Realm" and standings[1].place == 1 and standings[2].name == "Dan-Realm" and standings[3].name == "Cat-Realm" and standings[4].name == "Bob-Realm", "standings: Ann, Dan, Cat, Bob")
end)()

-- Poker handoff: a host hands the table to the next answering seat and keeps their chair; the successor carries it on
-- at once from the backup; one who never answers leaves it where it was; at a gold table the pool goes by trade first,
-- and the successor takes the table only once it has
;(function()
	local P = WantedPokerTestNS
	local Host, Client, Protocol, Net, Gold = P.PokerHost, P.PokerClient, P.PokerProtocol, P.PokerNet, P.PokerGold
	local nodes, queue, events = {}, {}, {}
	local now = 70000
	local function Now() return now end
	local function SendFrom(from) return function(target, tbl) queue[#queue + 1] = { from = from, to = target, text = ns.Sync:Encode(tbl) } return true end end
	local function Flush()
		local guard = 0
		while #queue > 0 do
			guard = guard + 1 assert(guard < 20000, "the table never settles")
			local m = tremove(queue, 1)
			local node = nodes[m.to]
			if node then
				local tbl = ns.Sync:Decode(m.text)
				if node.host and Protocol.TO_HOST[tbl.k] then node.host:Receive(m.from, tbl) end
				if node.player and Protocol.TO_PLAYER[tbl.k] then node.player:Receive(m.from, tbl) end
			end
		end
	end
	local function Tick(seconds)
		for _ = 1, seconds do
			now = now + 1
			for _, node in pairs(nodes) do if node.host then node.host:Tick() end if node.player then node.player:Tick() end end
			Flush()
		end
	end
	-- Each node does what Net does: takes a table handed to it, lets go of one handed on
	local function Node(name)
		events[name] = {}
		local node = { name = name }
		node.player = Client:New({ name = name, send = SendFrom(name), now = Now, on = function(event, ...)
			tinsert(events[name], { event, ... })
			if event == "handoff" then
				local backup = ...
				node.host = Host:Restore(backup, { name = name, send = SendFrom(name), now = Now, on = function(e, ...) tinsert(events[name], { "host:"..e, ... }) end })
				node.host:AnnounceTakeover()
			elseif event == "newHost" then
				local newHost = ...
				if node.host and node.host.handingTo == newHost and node.host:Handed() then node.host = nil end
			end
		end })
		nodes[name] = node
		return node
	end
	local function Count(name, event) local n = 0 for _, e in ipairs(events[name]) do if e[1] == event then n = n + 1 end end return n end
	local ann, bob, cat = Node("Ann-Realm"), Node("Bob-Realm"), Node("Cat-Realm")
	ann.host = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 0, startStack = 1000, levelMinutes = 5, maxSeats = 4, lateLevels = 0 }, send = SendFrom("Ann-Realm"), now = Now,
		on = function(e, ...) tinsert(events["Ann-Realm"], { "host:"..e, ... }) end })
	local t = ann.host
	ann.player:Join("Ann-Realm", t.id, 0) bob.player:Join("Ann-Realm", t.id, 0) cat.player:Join("Ann-Realm", t.id, 0)
	Flush()
	t:Start()
	Tick(1)
	check(t.phase == "playing", "under way")
	-- Hand off: Bob, the next seat, hosts at once; everyone follows without waiting Ann out; Ann keeps her chair
	check(t:Handoff() and t.handingTo == "Bob-Realm", "a chips table passes: Bob is next")
	Flush()
	check(bob.host and bob.host.term == 2 and bob.host.id == t.id and ann.host == nil and t.phase == "handed", "Bob has the table from the backup; Ann's copy is handed over")
	check(cat.player.host == "Bob-Realm" and ann.player.host == "Bob-Realm" and Count("Cat-Realm", "newHost") == 1 and Count("Cat-Realm", "hostGone") == 0, "Cat and Ann follow to Bob at once")
	check(bob.host:SeatOf("Ann-Realm") ~= nil and ann.player.seat ~= nil, "Ann keeps her seat")
	Tick(4)
	check(bob.host.phase == "playing" and bob.host.hand ~= nil, "the next hand is dealt under Bob")
	ann.player:Leave()
	Flush()
	check(bob.host:SeatOf("Ann-Realm") == nil and bob.host.entrants["Ann-Realm"].left, "and Ann can leave: the game goes on without her")
	-- The next seat whose client answers is the successor: a seat that missed its rounds is passed over
	local t2 = bob.host
	nodes["Cat-Realm"] = nil
	local dan = Node("Dan-Realm")
	t2.cfg.lateLevels = 6
	dan.player:Join("Bob-Realm", t2.id, 0)
	Flush()
	t2.seats[t2:SeatOf("Cat-Realm")].out = "missed"
	check(t2.seats[t2:Successor()].name == "Dan-Realm", "Cat's client is away: Dan is next in line")
	-- A successor who never takes it: the table stays
	nodes["Dan-Realm"] = nil
	check(t2:Handoff() and t2.handingTo == "Dan-Realm", "handing to Dan")
	Flush()
	Tick(Protocol.HANDOFF_SECONDS + 1)
	check(t2.handingTo == nil and t2.open and Count("Bob-Realm", "host:handoffFailed") == 1, "Dan never answered: the table stays with Bob")

	-- Gold: never handed on. The host holds the money, and the books stay with one bank
	local goldHost = Host:New({ name = "Ann-Realm", cfg = { kind = "tournament", entry = 100, startStack = 1000, levelMinutes = 5, maxSeats = 4, stakes = "gold" }, send = function() end, now = Now })
	goldHost:Receive("Ann-Realm", { k = "join", t = goldHost.id, b = 100 }) goldHost:Receive("Bob-Realm", { k = "join", t = goldHost.id, b = 100 })
	goldHost:Paid("Bob-Realm", 100, "trade")
	local okGold, whyGold = goldHost:Handoff()
	check(okGold == false and whyGold == "a gold table stays with the host who holds the money", "a gold table can't be handed on: "..tostring(whyGold))
end)()

-- Poker rejoin: a seat is remembered in the saved data and taken again after a reload: a join to its host at login,
-- given up after a minute without an answer; a table this character hosted is followed to whoever carries it on by
-- their ad; leaving, a refusal, a closed table or a day's age forget it; a practice table is never remembered
;(function()
	local P = WantedPokerTestNS
	local Net, Protocol = P.PokerNet, P.PokerProtocol
	local me = Net:Me()
	local function Sent(name, kind) for i = #addonSent, 1, -1 do local m = addonSent[i] if m.target == name and m.text:find("^P:") then local tbl = ns.Sync:Decode(m.text:match("^P:%w+:%d+/%d+:(.*)$")) if tbl and tbl.k == kind then return tbl end end end end
	local function Ad(sender, ad)
		ad.v = "0.1.0-dev"
		Fire("CHAT_MSG_ADDON", "WNTD", "T:zr"..math.random(1000, 9999)..":1/1:"..ns.Sync:Encode(ad), "CHANNEL", sender, nil, nil, nil, ns.Sync:GetInfo().channelName)
	end
	check(Net:JoinTable("Zed-Realm#rj", 300, "pass"), "sitting at Zed's locked table")
	local seat = Net:RememberedSeat()
	check(seat and seat.id == "Zed-Realm#rj" and seat.host == "Zed-Realm" and seat.buyin == 300 and seat.password == "pass", "the seat is remembered, password and all")
	-- The reload: the player object is gone; the saved seat stays
	Net:Player().left = true
	addonSent = {}
	check(Net:Rejoin() == true, "at login the seat is taken again")
	local join = Sent("Zed-Realm", "join")
	check(join and join.b == 300 and join.pw == "pass" and join.t == "Zed-Realm#rj", "a join to Zed with the buy-in and the password")
	for _ = 1, Protocol.REJOIN_GIVE_UP_SECONDS + 1 do clock = clock + 1 Net:Tick() end
	check(Net:RememberedSeat() == nil and Net:Player().left, "no answer for a minute: given up and forgotten")
	-- A table this character hosted, carried on by Cat: her ad sits us back down
	WantedPokerDB.seat = { id = me.."#old", host = me, buyin = 500, at = time() }
	check(Net:Rejoin() == false and Net:RememberedSeat() ~= nil, "hosted before: nothing to join yet, the seat is kept")
	addonSent = {}
	Ad("Cat-Realm", { id = me.."#old", h = "Cat-Realm", n = "Old Den", s = 2, m = 6, sb = 5, bb = 10, lo = 200, hi = 1000 })
	join = Sent("Cat-Realm", "join")
	check(join and join.b == 500 and join.t == me.."#old", "Cat advertises our old table: we join her")
	local st = { t = me.."#old", host = "Cat-Realm", e = 2, q = 1, me = 2, phase = "waiting", open = true, cfg = { sb = 5, bb = 10, buyMin = 200, buyMax = 1000, maxSeats = 6 },
		seats = { [1] = { n = "Cat-Realm", s = 1000 }, [2] = { n = me, s = 500 } } }
	Fire("CHAT_MSG_ADDON", "WNTD", "P:zw1:1/1:"..ns.Sync:Encode({ k = "welcome", t = me.."#old", v = "0.1.0-dev", st = st }), "WHISPER", "Cat-Realm")
	check(Net:State() and Net:State().host == "Cat-Realm" and Net:State().me == 2, "seated at Cat's")
	for _ = 1, Protocol.REJOIN_GIVE_UP_SECONDS + 1 do clock = clock + 1 Net:Tick() end
	check(Net:RememberedSeat() ~= nil and not Net:Player().left, "seated: the minute means nothing")
	Net:Leave()
	check(Net:RememberedSeat() == nil, "leaving forgets the seat")
	-- Hosting remembers; a practice table doesn't; a seat from yesterday is dropped
	check(Net:HostTable({ sb = 5, bb = 10, buyMin = 200, buyMax = 1000, maxSeats = 4 }, 1000) and Net:RememberedSeat().host == me, "hosting remembers the table")
	Net:Leave()
	check(Net:RememberedSeat() == nil, "closing forgets it")
	check(Net:HostTable({ sb = 5, bb = 10, buyMin = 200, buyMax = 1000, maxSeats = 4, bots = 2 }, 1000) and Net:RememberedSeat() == nil, "a practice table is never remembered")
	Net:Leave()
	WantedPokerDB.seat = { id = "X-Realm#y", host = "X-Realm", buyin = 1, at = time() - 7 * 3600 }
	check(Net:Rejoin() == false and Net:RememberedSeat() == nil, "a seat from yesterday is forgotten")
end)()

-- Poker polish: sounds and the your-turn alert, bet presets, hotkeys, pre-actions, the hand strength line, the all-in
-- confirm at gold tables, the four-colour deck, all switched from the window's options menu
;(function()
	local P = WantedPokerTestNS
	local Net, TableUI, Cards, Deal = P.PokerNet, P.PokerTable, P.PokerCards, P.PokerDeal
	local played = {}
	local realPlaySound, realKit = PlaySound, SOUNDKIT
	PlaySound = function(kit) played[#played + 1] = kit end
	SOUNDKIT = { IG_ABILITY_PAGE_TURN = 836, LOOT_WINDOW_COIN_SOUND = 120, READY_CHECK = 8960, IG_QUEST_LIST_COMPLETE = 878, IG_CREATURE_NEUTRAL_SELECT = 871, MAP_PING = 3175, IG_SPELLBOOK_OPEN = 1156, LFG_DENIED = 12889 }
	local function Played(kit) local n = 0 for _, k in ipairs(played) do if k == kit then n = n + 1 end end return n end
