	check(ns.Widgets:IsDialogShown(), "Report a bug asks what happened")
	ConfirmDialog("the pot paid the wrong seat")
	check(ns.Report:CountQueued() == queued + 1, "and queues a report for the developers")
	local tagged = false
	for _, line in ipairs(ns:GetLogLines(40)) do tagged = tagged or line:find("Poker: report", 1, true) ~= nil end
	check(tagged, "the poker context went into the log that travels with it")
	wipe(played)
	check(Cards:SuitColor(1) == Cards:SuitColor(4) and Cards:SuitColor(2) == Cards:SuitColor(3), "two colours: clubs like spades, diamonds like hearts")
	o.fourColor = true
	check(Cards:SuitColor(1) ~= Cards:SuitColor(4) and Cards:SuitColor(2) ~= Cards:SuitColor(3) and Cards:SuitColor(1) ~= Cards:SuitColor(2), "four colours: every suit its own")
	o.fourColor = false
	-- A heads-up hand through Net, Bob by whisper, as in the window test
	TableUI:Reset() -- as the page does before a table
	check(Net:HostTable({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 6, title = "Polish" }, 2000), "a chips table")
	local host = Net:HostedTable()
	TableUI:Hide()
	local id = host.id
	local msgNo = 0
	local function FromBob(tbl)
		tbl.t, tbl.v = id, "0.1.0-dev"
		msgNo = msgNo + 1
		local payload = ns.Sync:Encode(tbl)
		local total = math.ceil(#payload / 240)
		for part = 1, total do Fire("CHAT_MSG_ADDON", "WNTD", "P:zp"..msgNo..":"..part.."/"..total..":"..payload:sub((part - 1) * 240 + 1, part * 240), "WHISPER", "Bob-Realm") end
	end
	local function ToBob(kind)
		local messages, order = {}, {}
		for _, m in ipairs(addonSent) do
			if m.target == "Bob-Realm" and m.text:find("^P:") then
				local msgId, part, total, chunk = m.text:match("^P:(%w+):(%d+)/(%d+):(.*)$")
				local entry = messages[msgId]
				if not entry then entry = { parts = {}, total = tonumber(total) } messages[msgId] = entry order[#order + 1] = msgId end
				entry.parts[tonumber(part)] = chunk
			end
		end
		for i = #order, 1, -1 do
			local entry = messages[order[i]]
			if #entry.parts == entry.total then
				local tbl = ns.Sync:Decode(table.concat(entry.parts))
				if tbl and (not kind or tbl.k == kind) then return tbl end
			end
		end
	end
	addonSent = {}
	FromBob({ k = "join", b = 1000 })
	clock = clock + 1
	host:Tick()
	local key = ToBob("state").st.hand.key
	local secret = Deal:Secret()
	FromBob({ k = "commit", h = key, c = Deal:Commit(secret) })
	FromBob({ k = "reveal", h = key, s = secret })
	check(host.phase == "playing" and host.hand.toAct == 1, "dealt; heads-up the button (us) acts first")
	local parts = TableUI:GetParts()
	local function Logged(text) for _, line in ipairs(parts.lines or {}) do if line:find(text, 1, true) then return true end end return false end
	check(TableUI:IsShown(), "our turn with the window hidden: it opens")
	check(Played(8960) == 1 and Played(836) == 1, "a sound for the deal and one for our turn: turn "..Played(8960)..", deal "..Played(836)..", all "..#played)
	check(parts.strength:IsShown() and parts.strength._text ~= "" and (parts.strength._text:find("suited") or parts.strength._text:find("offsuit") or parts.strength._text:find("a pair of")), "the strength line before the flop: "..tostring(parts.strength._text))
	-- Presets: half the pot and the call on top of the bet to match; the most
	check(parts.presets[1]:IsShown() and parts.range[1] == 40 and parts.range[2] == 2000, "presets with the raise range 40 to 2000")
	TableUI.Preset(0.5)
	check(parts.amount == 40, "half pot: 20 + half of (30 + 10) = 40: "..tostring(parts.amount))
	TableUI.Preset(1)
	check(parts.amount == 60, "pot: 20 + (30 + 10) = 60: "..tostring(parts.amount))
	TableUI.Preset(2)
	check(parts.amount == 100, "twice the pot: 20 + 2 x (30 + 10) = 100: "..tostring(parts.amount))
	TableUI.Preset(0.25)
	check(parts.amount == 40, "a quarter pot is under the least raise: the least")
	TableUI.Preset(nil)
	check(parts.amount == 2000, "max")
	TableUI.Preset(0)
	check(parts.amount == 40, "min")
	-- The C key calls
	local function Felt(k) return (tostring(parts.seats[k].bet._text):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end
	check(parts.seats[1].status.text._text == "BB" and parts.seats[0].status.text._text == "Your turn" and Felt(1) == "20" and Felt(0) == "10", "before anyone acts, Bob's pill says BB, ours Your turn, and the felt shows the chips: "..Felt(1)..", "..Felt(0))
	parts.frame._scripts.OnKeyDown(parts.frame, "C")
	check(host.hand.toAct == 2 and Played(120) >= 1, "C calls, with the chips' sound")
	check(parts.seats[0].status.text._text == "Call" and Felt(0) == "20" and parts.seats[1].status.text._text == "To act", "our pill says Call and the felt shows 20 in front of us; Bob's pill says To act")
	-- A pre-action while Bob thinks: check/fold acts the moment the turn comes
	check(parts.checkFold:IsShown() and parts.callAny:IsShown(), "waiting: the pre-actions are offered")
	parts.checkFold:SetChecked(true)
	local before = { parts.board[1].arrivals, parts.board[3].arrivals, parts.board[4].arrivals }
	FromBob({ k = "act", h = key, q = host.seq, a = "check" })
	check(host.hand.street == "flop" and host.hand.toAct == 2 and parts.checkFold.checked, "the flop: Bob (the big blind) acts first; our pre-action waits")
	check(parts.board[1].arrivals == before[1] + 1 and parts.board[3].arrivals == before[2] + 1 and parts.board[4].arrivals == before[3] and parts.seats[0].cards[1].arrivals >= 1 and parts.seats[1].cards[2].arrivals >= 1, "the flop's three cards and everyone's hole cards were dealt in, once each: board "..parts.board[1].arrivals..","..parts.board[3].arrivals..","..parts.board[4].arrivals.." mine "..parts.seats[0].cards[1].arrivals.." bob "..parts.seats[1].cards[2].arrivals)
	FromBob({ k = "act", h = key, q = host.seq, a = "check" })
	check(host.hand.street == "turn" and host.hand.toAct == 2 and not parts.checkFold.checked, "Bob checks: our check went by itself, the turn is dealt and the pre-action is spent")
	check(Played(836) >= 3, "the deal sound again for the flop and the turn: "..Played(836))
	check(not parts.seats[0].bet:IsShown(), "the turn dealt: last street's labels are cleared")
	FromBob({ k = "act", h = key, q = host.seq, a = "bet", m = 20 })
	check(parts.seats[1].status.text._text == "Bet" and Felt(1) == "20", "Bob's pill says Bet; the felt shows the 20")
	local function Shown(list) local n = 0 for _, c in ipairs(list) do if c:IsShown() then n = n + 1 end end return n end
	check(Shown(parts.seats[1].chips) == 1 and Shown(parts.seats[0].chips) == 0, "one white chip by Bob's bet of a big blind; none by us")
	check(Shown(parts.potChips) == 3, "the pot of 60 (blinds, our call, Bob's bet) at blinds of 20: three white chips: "..Shown(parts.potChips))
	-- Stacks count the amount out in denominations: 140 big blinds is a black, a green, three reds
	local pool = {}
	for i = 1, 40 do pool[i] = NewMock() end
	local anchor = NewMock()
	local Lay = TableUI.LayStacks
	check(Lay(pool, 140 * 20, 20, anchor, false, 5) == 5, "140 big blinds: 100 + 25 + 5 + 5 + 5, five chips in three stacks")
	check(Lay(pool, 10, 20, anchor, false, 5) == 1, "half a big blind still shows one chip")
	check(Lay(pool, 0, 20, anchor, false, 5) == 0 and not pool[1]:IsShown(), "nothing: no chips")
	-- The pot's stacks stand under its amount, centred, on one line
	check(Lay(pool, 140 * 20, 20, anchor, nil, 5) == 5 and pool[1]._point[1] == "BOTTOM" and pool[1]._point[3] == "BOTTOM" and pool[1]._point[4] == -13 and pool[5]._point[4] == 13 and pool[5]._point[5] == pool[3]._point[5] + 6, "the pot's three stacks are centred under it, chips three apart up a stack")
	check(pool[1]._point[5] == -16 and pool[5]._point[5] == -16 and pool[3]._point[5] == -22, "each stack's top chip sits right under the amount; a taller stack reaches further down")
	-- Bet labels: by their seats, never on the cards, the pot, a box or each other, at six seats on the stock felt
	-- and at eight on the taller one (the felt's size as the window makes it: 980 - 220 - 22 by 560 - 130, or 640 - 130)
	for _, case in ipairs({ { 738, 430, 6 }, { 738, 510, 8 } }) do
		local w, h, n = case[1], case[2], case[3]
		local felt = NewMock() felt:SetSize(w, h)
		local boxes, labels = {}, {}
		for k = 0, n - 1 do
			local seat = NewMock() seat.bet = NewMock() seat.dealer = NewMock()
			local spot = TableUI.Place(seat, k, n, felt)
			local sx, sy = seat._point[4], seat._point[5]
			boxes[#boxes + 1] = { sx - 75, sx + 75, sy - 48, sy + 48 }
			local lx, ly = spot[1], spot[2]
			labels[#labels + 1] = { k = k, text = { lx - 30, lx + 30, ly - 7, ly + 7 }, chips = spot[3] and { lx + 30, lx + 75, ly - 7, ly + 7 } or { lx - 75, lx - 30, ly - 7, ly + 7 }, near = math.sqrt((lx - sx) ^ 2 + (ly - sy) ^ 2) }
		end
		local function Overlaps(a, b) return a[1] < b[2] and a[2] > b[1] and a[3] < b[4] and a[4] > b[3] end
		local fixed = { { -130, 130, -32, 32 }, { -60, 60, 77, 91 } } -- the cards, the pot amount
		for _, box in ipairs(boxes) do fixed[#fixed + 1] = box end
		for i, label in ipairs(labels) do
			local clear = label.near < 200
			for _, box in ipairs(fixed) do if Overlaps(label.text, box) or Overlaps(label.chips, box) then clear = false end end
			for j, other in ipairs(labels) do
				if j ~= i and (Overlaps(label.text, other.text) or Overlaps(label.text, other.chips) or Overlaps(label.chips, other.text)) then clear = false end
			end
			check(clear, ("%d seats on %dx%d: seat %d's bet at (%.0f, %.0f) is clear and near its box"):format(n, w, h, label.k, label.text[1] + 30, label.text[3] + 7))
		end
	end
	check(host.hand.toAct == 1 and parts.strength._text ~= "" and not parts.checkFold:IsShown(), "Bob bets: our turn, the strength line reads the board: "..tostring(parts.strength._text))
	parts.frame._scripts.OnKeyDown(parts.frame, "F")
	check((host.phase == "showdown" or host.hand.street == "done") and Played(1156) >= 1, "F folds, with the cards' sound")
	-- Table talk at the showdown: the buttons show, a line goes to the host, who tells everyone; it shows over the seat
	check(host.phase == "showdown" and parts.emotes[1]:IsShown(), "the table-talk buttons show at the showdown")
	addonSent = {}
	FromBob({ k = "say", e = 1 })
	local said = ToBob("said")
	check(said and said.s == 2 and said.e == 1, "Bob's line is relayed to him and to us")
	check(parts.seats[1].won._text:find("Nice hand", 1, true) ~= nil and Logged("Bob: Nice hand"), "and shows over his seat and in the log")
	addonSent = {}
	FromBob({ k = "say", e = 2 })
	check(ToBob("said") == nil, "a second line within three seconds is dropped")
	FromBob({ k = "say", e = 99 })
	check(ToBob("said") == nil, "a line that isn't one of the set is dropped")
	check(Played(12889) == 0, "folding is no showdown loss: no buzzer")
	-- All-in at a gold table asks first (the table closes after the hand under way; the showdown's clock runs out first)
	Net:Leave()
	clock = clock + P.PokerProtocol.SHOWDOWN_SECONDS + 1
	host:Tick()
	check(Net:HostedTable() == nil, "the table closed after the showdown")
	check(Net:HostTable({ sb = 10, bb = 20, buyMin = 400, buyMax = 2000, maxSeats = 6, stakes = "gold" }, 1000), "a gold table")
	parts.allin._scripts.OnClick(parts.allin)
	check(ns.Widgets:IsDialogShown(), "all in at a gold table asks first")
	ConfirmDialog()
	-- A silver game (blinds in whole silver) takes no copper: a half-pot preset and a typed amount round up to the silver
	local saved = parts.state
	parts.state, parts.range, parts.raiseLabel = { cfg = { stakes = "gold", sb = 100, bb = 200 }, hand = { pot = 725, cur = 0, legal = { call = 0 } } }, { 200, 2000 }, "Raise to"
	TableUI.Preset(0.5)
	check(parts.amount == 400, "half of 7s 25c rounds up to 4s, got "..tostring(parts.amount))
	parts.amountBox:SetText("5s 62c")
	parts.amountBox._scripts.OnTextChanged(parts.amountBox, true)
	check(parts.amount == 600, "a typed 5s 62c becomes 6s, got "..tostring(parts.amount))
	parts.state.cfg.bb = 250
	TableUI.Preset(0.5)
	check(parts.amount == 362, "with a 2s 50c big blind the game is in copper: no rounding, got "..tostring(parts.amount))
	parts.state, parts.range = saved, nil
	-- Boxes are filled the way amounts are typed, not with the coin icons: the rebuy box opens on 4s, which the box reads back
	parts.rebuy._scripts.OnClick(parts.rebuy)
	check(lastDialog and lastDialog.input and lastDialog.input.value == "4s", "the rebuy box opens on 4s, got "..tostring(lastDialog and lastDialog.input and lastDialog.input.value))
	ConfirmDialog(lastDialog.input.value)
	Net:Leave()
	PlaySound, SOUNDKIT = realPlaySound, realKit
end)()

-- Capture fronts: a sample every 30 s while the player stands in a point able to fight, kept in the presence book for
-- the app and told to our side; the holders as the site told the app; lanes taken in order; the map, minimap, bar,
-- waypoints and alerts
;(function()
	local C, db = ns.Captures, ns.db
