	C:TakeSiege(nil, { hb = { h = 3, a = 1 } })
	ns.UI:Refresh(true)
	check(shows("THIS WEEK") and shows("Horde 3 · Alliance 1") and shows("Horde 3 · Alliance 1 this week") and shows("no wins yet"), "the week's wins per front in the results and on the front")
	fits()
