	WorldMapFrame.GetMapID, WorldMapFrame.IsShown = real.GetMapID, real.IsShown
	ns.CapturesHUD:Update()
end)()
-- The upcoming siege evenings: Captures:Evenings (a week from tonight, or from tomorrow once tonight's window has
-- closed, the fronts the catch-up named in place), the Siege page's Upcoming card and the Dashboard's card
;(function()
	local C, HUD = ns.Captures, ns.CapturesHUD
	local real = { Warn = ns.Alerts.Warn, PlaySound = PlaySound }
	ns.Alerts.Warn = function() end
	PlaySound = function() end
	local function On(f)
		local on, p = f._shown, f._parent
		while on and p do on, p = p._shown, p._parent end
		return on
	end
	local function Plain(text) return (text:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end
	local function count(text, pattern)
		local n = 0
		for _, f in ipairs(Mock.fontStrings) do
			if type(f._text) == "string" and On(f) and (pattern and Plain(f._text):find(text) or not pattern and Plain(f._text) == text) then n = n + 1 end
		end
		return n
	end
	local function shows(text) for _, f in ipairs(Mock.fontStrings) do if type(f._text) == "string" and On(f) and Plain(f._text):find(text, 1, true) then return true end end return false end
	local function Day(t) return date("%Y%m%d", t) end
	-- Tonight's siege at 7 PM on the client's clock, the next one named
	local t = date("*t", clock)
	local start = time({ year = t.year, month = t.month, day = t.day, hour = 19, min = 0, sec = 0 })
	C:TakeSiege({ front = "hb", start = start, ["end"] = start + 3 * 3600, next = { front = "av", start = start + 86400, ["end"] = start + 86400 + 3 * 3600 } }, nil)
	local evenings = C:Evenings(7, clock)
	local closed = start + 3 * 3600 <= clock -- the test's clock may be past tonight's window already
	check(#evenings == 7 and evenings[1].today == not closed and Day(evenings[1].day) == Day(clock + (closed and 86400 or 0)), "seven evenings from tonight, or tomorrow once tonight's window has closed")
	for i, e in ipairs(evenings) do
		check(date("%H:%M", e.start) == "19:00" and e["end"] - e.start == 3 * 3600 and Day(e.day) == Day(e.start) and (i == 1 or Day(e.day) == Day(evenings[i - 1].day + 86400)),
			"each evening a day on, at the known siege's hours: "..tostring(date("%c", e.start)))
		local expected = Day(e.day) == Day(start) and "hb" or Day(e.day) == Day(start + 86400) and "av" or nil
		check((e.front and e.front.id) == expected, "the catch-up's fronts on their evenings, none on the rest: "..tostring(e.front and e.front.id))
	end
	check(C:Evenings(7, start + 3 * 3600)[1].front.id == "av" and not C:Evenings(7, start + 3 * 3600)[1].today, "once tonight's window closes, tomorrow's is first")
	-- The Siege page's Upcoming card: the rows, the windows, the fronts named, the rest to be picked, tonight marked
	ns.UI:Show("siege")
	check(shows("UPCOMING") and count("^%a%a%a %d+ %a%a%a$", true) >= 7 and count("7 to 10 PM") == 7, "the Upcoming card: seven days with the window in the client's clock")
	check(count("Hillsbrad Foothills") >= 1 and count("Ashenvale") >= 1 and count("front picked the evening before") == 5, "the fronts named for two evenings, the rest picked the evening before")
	-- (The tonight card and the fronts' pill go by the PC's own day, which the test's clock isn't: only the row's pill here)
	check(count("TONIGHT") == (closed and 0 or 1), "tonight's row marked: "..count("TONIGHT"))
	check(count("Open the map") == 1 + 3 + 2, "Open the map on the two evenings with a front: "..count("Open the map"))
	-- The Dashboard's card: the next three evenings in a line each; click for the Siege page
	ns:RunCommand("demo", "")
	ns.UI:Show("home")
	for i, e in ipairs(C:Evenings(3, clock)) do
		local line = format("%s %s · %s", date("%a", e.day), HUD:HourText(e.start), e.front and e.front.zone or "to be picked")
		check(count(line) == 1, "the Dashboard's upcoming line "..i..": "..line)
	end
	check(shows("UPCOMING SIEGES"), "under its label")
	for _, f in ipairs(Mock.fontStrings) do
		if f._text == "UPCOMING SIEGES" and On(f) then f._parent:Click() end
	end
	check(ns.UI:IsShown("siege"), "clicking the card opens the Siege page")
	-- Nothing known: the site's window on the page, and said so on the Dashboard
	C:TakeSiege(nil, nil)
	ns.UI:Show("siege")
	check(count("7 to 10 PM Eastern") == 7 and count("front picked the evening before") == 7 and count("Open the map") == 3, "no siege known: the site's window, every front to be picked")
	ns.UI:Show("home")
	local upcomingTip
	for _, f in ipairs(Mock.created) do
		if rawget(f, "tooltipTitle") == "Upcoming sieges" then upcomingTip = f.tooltipText end
	end
	check(shows("No siege picked yet") and not shows("Picked each evening") and upcomingTip and upcomingTip:find("picked the evening before", 1, true),
		"the Dashboard says none is picked yet; when they're picked is on hover")
	ns:RunCommand("demo", "")
	ns.UI:GetFrame():Hide()
	ns.Alerts.Warn, PlaySound = real.Warn, real.PlaySound
end)()
-- Skull and Flare: secure buttons the game runs itself, set up out of combat only. Skull marks the target with the
-- skull when it's a bounty or Kill on Sight enemy and we lead or assist the group (its action sits under the button
-- name the game switches to only for a target we can attack, so in a fight it never marks anyone else); Flare places a
-- world marker for the rally leader. Not set up, a click says why; in a fight Skull only says it can't change.
;(function()
	local Rally = ns.Rally
	local skull, flare = _G.WantedRallySkullButton, _G.WantedRallyFlareButton
	check(skull and flare and skull:GetAttribute("marker") == 8 and skull:GetAttribute("unit") == "target" and skull:GetAttribute("action") == "set"
		and skull:GetAttribute("harmbutton") == "skull" and flare:GetAttribute("marker") == 1,
		"the Skull and Flare buttons are made, named for /click, with the skull for attackable targets and a world marker")
	local realInfo = C_Map.GetMapInfo
	C_Map.GetMapInfo = function(id) return id == 1 and { name = "Durotar", mapType = 3 } or nil end
	local role = nil
	_G.UnitIsGroupLeader = function() return role == "leader" end
	_G.UnitIsGroupAssistant = function() return role == "assist" end
	_G.UnitCanAttack = function(_, unit) local e = enemyUnits[unit] return e ~= nil and (e.faction or "Alliance") ~= "Horde" end
	local said = #printed
	enemyUnits.target = { guid = "Player-9-SKULL1", name = "Skull Target", class = "ROGUE", level = 20 }
	Fire("PLAYER_TARGET_CHANGED")
	check(skull:GetAttribute("type-skull") == nil and skull:GetAttribute("type") == nil, "not the group's leader or an assistant: Skull does nothing")
	skull._scripts.PostClick(skull, "LeftButton")
	check(#printed == said + 1 and printed[#printed]:find("leader or assistants", 1, true), "and a click says why: "..tostring(printed[#printed]))
	role = "assist"
	Fire("PLAYER_TARGET_CHANGED")
	check(skull:GetAttribute("type-skull") == nil and skull.why:find("no bounty", 1, true), "a target with no bounty and not on Kill on Sight isn't marked: "..tostring(skull.why))
	-- An enemy we can't attack (not flagged, a sanctuary) never sets it up: the game's click would do nothing
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", true)
	local realCanAttack = UnitCanAttack
	_G.UnitCanAttack = function() return false end
	Fire("PLAYER_TARGET_CHANGED")
	check(skull:GetAttribute("type-skull") == nil and skull.why:find("can't attack", 1, true), "a Kill on Sight enemy we can't attack isn't set up: "..tostring(skull.why))
	_G.UnitCanAttack = realCanAttack
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", false)
	RunTimers()
	-- Put on Kill on Sight while targeted: set up again without a target change
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", true)
	RunTimers()
	check(skull:GetAttribute("type-skull") == "raidtarget" and skull:GetAttribute("type") == nil,
		"our target put on Kill on Sight: Skull marks it, under the attackable-target button only")
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", false)
	RunTimers()
	check(skull:GetAttribute("type-skull") == nil, "taken off Kill on Sight: Skull does nothing again")
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", true)
	RunTimers()
	said = #printed
	skull._scripts.PostClick(skull, "LeftButton")
	check(#printed == said, "a click that marks says nothing")
	-- In a fight the game forbids changes: it stays as it was, and a click that can't act says only that
	inCombat = true
	enemyUnits.target = { guid = "Player-9-SKULL2", name = "Plain Target", class = "ROGUE", level = 20, faction = "Horde" }
	Fire("PLAYER_TARGET_CHANGED")
	ns.Enemies:SetKoS("Player-9-SKULL1", "Skull Target", false)
	RunTimers()
	check(skull:GetAttribute("type-skull") == "raidtarget", "nothing is changed in a fight")
	skull._scripts.PostClick(skull, "LeftButton")
	check(#printed == said + 1 and printed[#printed]:find("can't be changed in a fight", 1, true), "a click in a fight on a target we can't attack says why, plainly: "..tostring(printed[#printed]))
	inCombat = false
	Fire("PLAYER_REGEN_ENABLED")
	check(skull:GetAttribute("type-skull") == nil, "and it's set up again when the fight ends")
	enemyUnits.target = nil
	-- Flare is for the rally leader
	role = "leader"
	Fire("GROUP_ROSTER_UPDATE")
	check(flare:GetAttribute("type") == nil and flare.why:find("rally leader", 1, true), "Flare waits for a rally")
	check(Rally:Claim() == nil and flare:GetAttribute("type") == "worldmarker", "leading the rally, Flare places a world marker")
	ns.NearbyWindow:SetShown(true)
	ns.NearbyWindow:Refresh()
	check(skull:IsShown() and flare:IsShown(), "the leader's rally line shows Skull and Flare")
	Rally:End()
	check(flare:GetAttribute("type") == nil, "the rally over, Flare does nothing")
	RunTimers()
	ns.NearbyWindow:Refresh()
	check(not skull:IsShown() and not flare:IsShown(), "and the buttons go")
	_G.UnitIsGroupLeader, _G.UnitIsGroupAssistant, _G.UnitCanAttack = nil, nil, nil
	C_Map.GetMapInfo = realInfo
end)()
-- Layers: our layer of the zone is read from the GUIDs of the creatures we look at, goes out with our hello, rally
-- position and point presence, and the rally line says when the leader is on another one. A layer hop asks a Wanted
-- player on the rally's layer for an invite by whisper: their addon invites (never in a fight, a full group, or with
-- hosting off), ours accepts the invite from that host alone, holds the group twenty seconds, then leaves unless we
-- stay or the host leads the rally; still on the old layer at fifteen seconds, it says so and leaves.
;(function()
	local Shard, Rally, Sync = ns.Shard, ns.Rally, ns.Sync
	local startClock = clock
	local real = { GetMapInfo = C_Map.GetMapInfo, GetBestMapForUnit = C_Map.GetBestMapForUnit, IsInGroup = IsInGroup, IsInRaid = IsInRaid,
		groupSize = groupSize, C_PartyInfo = C_PartyInfo, AcceptGroup = AcceptGroup, UnitInParty = UnitInParty, UnitInRaid = UnitInRaid, Warn = ns.Alerts.Warn }
	local maps = { [1] = { name = "Durotar", mapType = 3, parentMapID = 2 }, [2] = { name = "Kalimdor", mapType = 2 }, [1424] = { name = "Hillsbrad Foothills", mapType = 3, parentMapID = 1415 }, [1415] = { mapType = 2 } }
	local best = 1
	C_Map.GetMapInfo = function(id) return maps[id] end
	C_Map.GetBestMapForUnit = function() return best end
	local inGroup, invited, accepted, left, warned = {}, {}, 0, 0, {}
	IsInGroup = function() return next(inGroup) ~= nil end
	IsInRaid = function() return false end
	UnitInParty = function(n) return inGroup[n] or nil end
	UnitInRaid = function() return nil end
	C_PartyInfo = { InviteUnit = function(name) invited[#invited + 1] = name end, LeaveParty = function() left = left + 1 wipe(inGroup) end }
	AcceptGroup = function() accepted = accepted + 1 end
	ns.Alerts.Warn = function(_, title, sub) warned[#warned + 1] = title.." "..(sub or "") end
	hiddenPopups = {}
	local function Said(text)
		for i = #printed, math.max(1, #printed - 4), -1 do if printed[i]:find(text, 1, true) then return printed[i] end end
		return nil
	end
	local channelName, msgs = Sync:GetInfo().channelName, 0
	local function Msg(tag, tbl)
		msgs = msgs + 1
		return tag..":sh"..msgs..":1/1:"..Sync:Encode(tbl)
	end
	local function Hear(tag, tbl, how, sender)
		Fire("CHAT_MSG_ADDON", "WNTD", Msg(tag, tbl), how, sender, nil, nil, nil, how == "CHANNEL" and channelName or nil)
		RunFrames() -- a hello waits out any background work
	end
	local function LastWhisper(tag)
		for i = #addonSent, 1, -1 do
			local m = addonSent[i]
			if m.chatType == "WHISPER" and m.text:sub(1, 2) == tag..":" then
				return m.target, Sync:Decode(m.text:match("^%u:%w+:%d+/%d+:(.*)$"))
			end
		end
	end
	-- Detection from a GUID
	check(Shard:ParseGUID("Creature-0-4615-1-497-3123-0000123ABC") == "4615-1-497", "a creature's GUID names its layer")
	check(Shard:ParseGUID("Vehicle-0-4621-0-507-5624-0004C97619") == "4621-0-507", "so does a vehicle's")
	for _, bad in ipairs({ "Player-4613-015669D9", "Pet-0-4615-1-544-1863-0102C1A2B3", "Creature-0-4615-1", 42, false }) do
		check(Shard:ParseGUID(bad) == nil, "no layer in "..tostring(bad))
	end
	local A, B = "4615-1-497", "4615-1-501"
	Fire("ZONE_CHANGED_NEW_AREA")
	check(Shard:Current() == nil and not Shard:IsFresh(), "no layer known before a creature is seen")
	local n = 0
	local function Look(key, unit, event, guid)
		n = n + 1
		local was = enemyUnits[unit]
		enemyUnits[unit] = { guid = guid or format("Creature-0-%s-%d-%010X", key, 3000 + n, n), npc = true }
		Fire(event, unit)
		enemyUnits[unit] = was
	end
	Look(A, "mouseover", "UPDATE_MOUSEOVER_UNIT")
	check(Shard:Current() == A and Shard:IsFresh(), "a creature under the mouse gives the layer, fresh")
	Look(A, "target", "PLAYER_TARGET_CHANGED")
	Look(A, "softenemy", "PLAYER_SOFT_ENEMY_CHANGED")
	Look(B, "nameplate70", "NAME_PLATE_UNIT_ADDED")
	check(Shard:Current() == A, "one creature from over a zone border doesn't change it")
	for _ = 1, 5 do Look(B, "nameplate70", "NAME_PLATE_UNIT_ADDED", "Creature-0-4615-1-501-3000-0000000001") end
	check(Shard:Current() == A, "the same creature seen again counts once")
	for _ = 1, 8 do Look(B, "nameplate70", "NAME_PLATE_UNIT_ADDED") end
