-- The layer is stamped on what this client records: presence samples, kills, deaths, spotted records and our own
-- sightings carry l (Shard:Current()), left out while it isn't known
;(function()
	local Shard, Store, db = ns.Shard, ns.Store, ns.db
	local real = { C_Map = C_Map, SendPoint = ns.Sync.SendPoint }
	C_Map = { GetBestMapForUnit = function() return 1424 end, GetPlayerMapPosition = function() return { x = 0.523, y = 0.309 } end,
		GetMapInfo = function(id) if id == 1415 then return { mapType = 2 } end return { mapType = 3, parentMapID = 1415 } end }
	ns.Sync.SendPoint = function() return true end
	Fire("ZONE_CHANGED_NEW_AREA")
	check(Shard:Current() == nil, "no layer known yet")
	local function Kill(id) return Store:NewRecord("kill", { killer = "Player-1-ME", killerName = Store:GetOrigin(), victim = "Player-9-L"..id, victimName = "Layer "..id, deathId = "layer-"..id, zone = "Hillsbrad Foothills", honor = true }) end
	check(Kill(0).data.l == nil, "a kill before the layer is known carries no l")
	local n = 0
	local function Look(key)
		n = n + 1
		enemyUnits.mouseover = { guid = format("Creature-0-%s-%d-%010X", key, 4000 + n, n), npc = true }
		Fire("UPDATE_MOUSEOVER_UNIT", "mouseover")
		enemyUnits.mouseover = nil
	end
	for _ = 1, 3 do Look("4615-1-497") end
	check(Shard:Current() == "4615-1-497", "the layer is read")
	check(Kill(1).data.l == "4615-1-497", "a kill carries the layer")
	local r = Store:NewRecord("death", { deathId = "layer-2", victim = "Player-9-L2", victimName = "Layer Two", victimFaction = "Alliance", zone = "Hillsbrad Foothills" })
	check(r.data.l == "4615-1-497", "so does a death")
	r = Store:NewRecord("spotted", { target = "Player-9-L2", zone = "Hillsbrad Foothills" })
	check(r.data.l == "4615-1-497", "and a spotted record")
	r = Store:NewRecord("mark", { about = "Player-9-L2", category = "test" })
	check(r.data.l == nil, "other kinds don't")
	Store:AddSighting("Player-9-L2", "Hillsbrad Foothills", 50, 50, 1424)
	local own = Store:SightingIterator()()
	check(own.l == "4615-1-497" and own.by == nil, "our own sighting carries the layer")
	Store:AddSighting("Player-9-L2", "Hillsbrad Foothills", 50, 50, 1424, "Thrall")
	check(Store:SightingIterator()().l == nil, "a shared one doesn't: the sharer's layer isn't ours")
	db.presence = {}
	clock = clock + 30
	ns.Captures:Sample()
	local key = next(db.presence)
	local entry = key and db.presence[key]
	check(entry and entry.p == "hb-mid-2" and entry.l == "4615-1-497", "a presence sample carries the layer: "..tostring(entry and entry.l))
	db.presence = {}
	Fire("ZONE_CHANGED_NEW_AREA")
	C_Map, ns.Sync.SendPoint = real.C_Map, real.SendPoint
end)()
-- The target layer of a zone: the siege's layer while the siege is on at that front, else the zone's fight layer as
-- the site last said it (the catch-up's layers, for a quarter hour), else this client's own estimate from the channel
-- (deaths heard there and Wanted players of our side heard there, by layer, from five). One line says it.
;(function()
	local Shard, Store, C, Sync = ns.Shard, ns.Store, ns.Captures, ns.Sync
	local startClock = clock
	local real = { C_Map = C_Map, GetZoneText = GetZoneText, SendPoint = Sync.SendPoint }
	local best = 1424
	C_Map = { GetBestMapForUnit = function() return best end, GetPlayerMapPosition = function() return { x = 0.523, y = 0.309 } end,
		GetMapInfo = function(id) if id == 1415 then return { mapType = 2 } end return { mapType = 3, parentMapID = 1415 } end }
	GetZoneText = function() return best == 1424 and "Hillsbrad Foothills" or "Durotar" end
	local told = {}
	Sync.SendPoint = function(_, t) told[#told + 1] = t return true end
	local channelName, msgs = Sync:GetInfo().channelName, 0
	local function Hear(tag, tbl, sender)
		msgs = msgs + 1
		Fire("CHAT_MSG_ADDON", "WNTD", tag..":tl"..msgs..":1/1:"..Sync:Encode(tbl), "CHANNEL", sender, nil, nil, nil, channelName)
		RunFrames() -- a hello waits out the background work the new records queued
	end
	local HB, AH = "Hillsbrad Foothills", "Arathi Highlands"
	local L = function(n) return "4615-1-"..n end
	clock = clock + 601 -- the deaths and players heard before have lapsed
	Fire("ZONE_CHANGED_NEW_AREA")
	C:TakeSiege(nil, nil)
	Shard:TakeLayers(nil)
	check(Shard:Target(HB) == nil and Shard:TargetText(HB) == nil, "no target before anything is heard")
	-- The estimate: deaths heard with a layer, five of them
	local deaths = 0
	local function Death(key, zone)
		deaths = deaths + 1
		Store:NewRecord("death", { deathId = "tl-"..deaths, victim = "Player-9-TL"..deaths, victimName = "Target "..deaths, victimFaction = "Alliance", zone = zone or HB, l = key })
	end
	for _ = 1, 4 do Death(L(501)) end
	check(Shard:Target(HB) == nil, "four deaths on a layer name no fight layer")
	Death(L(501))
	local key, kind = Shard:Target(HB)
	check(key == L(501) and kind == "fight", "five do: the fight layer, "..tostring(key))
	Death(L(501), AH)
	check(Shard:Target(AH) == nil, "a death in another zone counts there, not here")
	Store:NewRecord("death", { deathId = "tl-1", victim = "Player-9-TL1", victimName = "Target 1", victimFaction = "Alliance", zone = HB, l = L(503) })
	check(Shard:Target(HB) == L(501), "the same death told again counts once")
	-- Wanted players of our side heard in the zone count too; a tie goes to the lower id
	for i = 1, 5 do Hear("H", { c = {}, l = L(497), lm = 1424 }, "Peer "..i) end
	check(Shard:Target(HB) == L(497), "five players and five deaths tie: the lower id, "..tostring(Shard:Target(HB)))
	Death(L(501))
	check(Shard:Target(HB) == L(501), "six deaths beat five players")
	Hear("H", { c = {}, l = L(497), lm = 1 }, "Peer 6")
	check(Shard:Target(HB) == L(501), "a player in another zone doesn't count here")
	Hear("H", { c = {}, l = L(497), lm = 1424 }, "Peer 6")
	check(Shard:Target(HB) == L(497), "six players beat six deaths: the lower id")
	-- The other side's players, through the group's bridges (Shard:NoteFar): counted like ours, the most any one sender
	-- says of a layer, so two bridges telling of the same players don't double them
	Shard:NoteFar("bnet:7", { { m = 1424, l = L(501), n = 2 } })
	check(Shard:Target(HB) == L(501), "the other side's players tip the fight layer: "..tostring(Shard:Target(HB)))
	Shard:NoteFar("bnet:8", { { m = 1424, l = L(501), n = 2 }, { m = 1424, l = L(497), n = 1 } })
	check(Shard:Target(HB) == L(501), "two senders telling of the same players count once")
	Shard:NoteFar("bnet:7", { { m = 1424, l = L(497), n = 3 } })
	check(Shard:Target(HB) == L(497), "a sender's newer word replaces its old one: "..tostring(Shard:Target(HB)))
	Shard:NoteFar("bnet:8", { { m = "1424", l = L(501), n = 9 }, { m = 1424, l = 12, n = 9 } })
	check(Shard:Target(HB) == L(497), "malformed entries are left out")
	local summary = Shard:FarSummary()
