	check(Shard:Target(HB) == L(519) and Shard:Target(AH) == L(517) and news[#news] == "layer:"..L(519), "the catch-up's siege layer and fight layers: "..tostring(Shard:Target(HB)))
	WantedAppCatchup = { [ns.db.accountMark] = { t = 1, records = {} } }
	ns.Catchup:Import()
