	-- The Dashboard: the line of marks, a fix line for each red step, and it opens Website & app
	ns.UI:Show("home")
	local home = Setup.cards.home
	local function Texts(card)
		local texts = { card.label._text }
		for _, row in ipairs(card.rows) do
			for _, fs in ipairs({ row.name, row.title, row.detail, row.box }) do
				if fs:IsShown() and type(fs._text) == "string" then texts[#texts + 1] = fs._text end
			end
		end
		return table.concat(texts, "\n")
	end
	local texts = Texts(home)
	check(home and home:IsShown() and home.label._text == "Your setup", "the Dashboard's setup card says what's missing")
	check(home.rows[3].name._text == "In the group" and home.rows[4].name._text == "Enemy plates", "the one-line card uses the short names, got "..tostring(home.rows[3].name._text))
	-- Each mark explains its step on hover: the fix, with the address, for a red one
	check(not texts:find("Get it, start it", 1, true) and not texts:find("Press V", 1, true) and home:GetHeight() <= 70, "no fix lines on the card: one line of marks")
	local appTip, platesTip, addonTip = home.rows[2].hit.tooltipText, home.rows[4].hit.tooltipText, home.rows[1].hit.tooltipText
	check(home.rows[2].hit:IsShown() and home.rows[2].hit.tooltipTitle == "Wanted app running" and appTip:find("Get it, start it, then /reload.", 1, true)
		and appTip:find("wanteddeadordead.com/app", 1, true) and appTip:find("No Wanted app on this computer", 1, true), "the app's mark: its detail, then the fix with the address")
	check(platesTip:find("Press V, or Interface > Names > Enemy Players.", 1, true), "the plates' mark: how to turn them on")
	check(home.rows[2].hit._clicks == false, "a mark lets the click through to the card")
	check(addonTip and not addonTip:find("\n\n", 1, true), "a green mark: its detail, no fix")
	-- Fixed one by one
	cvars.nameplateShowEnemies = "1"
	check(Setup:Steps()[4].state == "ok", "plates on: green")
	WantedAppInfo = { running = "0.2.54", latest = "0.2.54" }
	check(Setup:Steps()[2].state == "ok", "the app running: green")
	C_Club = { GetSubscribedClubs = function() return { { clubId = "23053871", name = "Wanted", clubType = 0 } } end, GetClubMembers = function() return {} end }
	ns.Bridge.clubId = "23053871"
	check(Setup:Steps()[3].state == "ok", "in the group: green")
	check(Setup:AllSet(), "all set")
	ns.db.settings.siege = true
	ns.newerVersion = "9.9.9"
	local addon = Setup:Steps()[1]
	check(addon.state == "bad" and addon.url == "https://wanteddeadordead.com/addon" and addon.detail:find("9.9.9", 1, true), "a newer version out: the addon step red, with the site's addon page")
	ns.newerVersion = nil
	ns.UI:Show("home")
	check(home.label._text == "Your setup: all set" and home:GetHeight() <= 70, "all set: the Dashboard's card says so in one line")
	-- The Website & app page: every step, the invite to copy when not in the group, and Turn on sets the plates
	ns.Bridge.clubId = 0
	cvars.nameplateShowEnemies = "0"
	ns.UI:Show("web")
	local web = Setup.cards.web
	-- The steps on the step bar: set ones ticked, red ones crossed; the first not set has its fix and address under it
	local dots = web.bar.dots
	check(dots[1].mark._texture:find("tick$") and dots[2].mark._texture:find("tick$") and dots[3].mark._texture:find("cross$") and dots[4].mark._texture:find("cross$"),
		"Website & app: the steps on the step bar, the set ones ticked, the missing ones crossed")
	check(dots[3].tooltipTitle == "In the Wanted Battle.net group" and dots[3].tooltipText:find("Join it", 1, true) and dots[4].tooltipText:find("Press V", 1, true),
		"each dot's tooltip is its detail and fix")
	check(web.rows[3].box:IsShown() and web.rows[3].box._text == ns.Bridge.INVITE_URL and web.fix._text:find("^In the Wanted Battle.net group: Join it"),
		"the first one not set: its fix, and the group's invite to copy, under the bar")
	local turnOn = web.rows[4].button
	check(not turnOn:IsShown(), "the next one waits its turn")
	ns.Bridge.clubId = "23053871"
	ns.UI:Refresh(true)
	web.Refresh()
	check(turnOn:IsShown() and turnOn._scripts.OnClick and not web.rows[3].box:IsShown() and dots[3].mark._texture:find("tick$"), "in the group: the nameplates step, with Turn on")
	turnOn._scripts.OnClick(turnOn)
	check(not turnOn:IsShown() and not web.fix:IsShown() and dots[4].mark._texture:find("tick$"), "the button goes, the step is ticked")
	ns.Bridge.clubId = 0
	check(cvars.nameplateShowEnemies == "1" and Setup:Steps()[4].state == "ok", "Turn on sets the enemy nameplates on")
	-- The tour: /wanted tour opens the card on the first page; Next opens each stop's page behind it and borders the
	-- part it talks about; the page is remembered when it's closed; a fight closes it and the end of the fight brings it
	-- back; Finish on the last page ends it with the app prompt
	do
		local Tour, f = ns.Tour, nil
		ns.db.tour = nil
		ns:RunCommand("tour", "")
		f = WantedTourFrame
		check(Tour:IsShown() and f.counter._text == "First steps · 1 of "..#Tour.STOPS and ns.UI:IsShown("home"), "the tour opens on the Dashboard: "..tostring(f.counter._text))
		-- The races and guild wars: four stops on Guild Wars, the wars after launch; no stop for the old siege nights
		local titles, guildWars = {}, 0
		for _, stop in ipairs(Tour.STOPS) do
			titles[#titles + 1] = stop.title
			guildWars = guildWars + (stop.page == "guildwars" and 1 or 0)
			check(stop.page ~= "siege" and not stop.text:find("siege front", 1, true), "no stop describes the old siege nights: "..stop.title)
		end
		local all = table.concat(titles, ", ")
		check(guildWars == 4 and all:find("Tonight's races, Influence, The race HUD, Live numbers, Guild wars come after launch", 1, true), "the tour's race stops: "..all)
		check(Setup.cards.home and f.title._text == "Welcome to Wanted", "the first page welcomes")
		f.next:Click()
		check(f.counter._text:find("2 of", 1, true) and ns.UI:IsShown("home"), "the lights page stays on the Dashboard")
		f.next:Click()
		check(ns.UI:IsShown("enemies") and ns.NearbyWindow:IsShown(), "Enemies opens the page and the Nearby window")
		f.next:Click()
		check(ns.UI:IsShown("board") and f.title._text == "The Board", "the Board page")
		-- The settings stop opens the tab its invite box sits on
		local invite = ns.UI:MarkFrame("invite")
		check(invite and invite:IsVisible(), "the invite mark opens Sharing and display, so the box it borders is on screen")
		f.back:Click()
		check(ns.UI:IsShown("enemies") and f.counter._text:find("3 of", 1, true), "Back goes back")
		f.close:Click()
		check(not Tour:IsShown() and ns.db.tour.page == 3 and ns.db.tour.seen, "closed: the page is remembered")
		ns:RunCommand("tour", "")
		check(Tour:IsShown() and f.counter._text:find("3 of", 1, true), "/wanted tour continues where it was")
		inCombat = true
		Fire("PLAYER_REGEN_DISABLED")
		check(not Tour:IsShown(), "a fight closes it")
		inCombat = false
		Fire("PLAYER_REGEN_ENABLED")
		RunTimers()
		check(Tour:IsShown() and f.counter._text:find("3 of", 1, true), "the end of the fight brings it back")
		local prompted = false
		local realPrompt = ns.PromptForApp
		ns.PromptForApp = function() prompted = true end
		for _ = 1, #Tour.STOPS do f.next:Click() end
		ns.PromptForApp = realPrompt
		check(not Tour:IsShown() and ns.db.tour.done and prompted, "Finish on the last page ends it with the app prompt")
	end
	-- The poker tour: the first Poker page opens it; Next waits for a table to be hosted; the table's bar and log are
	-- marked once it is; /wanted tour poker comes back where it was; Finish ends it without the app prompt
	do
		local Tour, f = ns.Tour, WantedTourFrame
		local P = WantedPokerTestNS
		ns.db.tour.poker = nil
		if P.PokerTable:IsShown() then P.PokerTable:Hide() end
		ns.UI:Show("poker")
		check(Tour:IsShown() and f.counter._text == "Poker · 1 of 5" and f.title._text == "The Wanted table", "the first Poker page starts the poker tour: "..tostring(f.counter._text))
		f.next:Click()
		local waitTick = tickers[#tickers] -- the tour looking again for the table window, once a second
		check(f.title._text == "Host a table" and not f.next:IsEnabled() and f.next:GetText() == "Host a table first", "Next waits for a table: "..tostring(f.next:GetText()))
		check(P.PokerNet:HostTable({ sb = 5, bb = 10, buyMin = 200, buyMax = 1000, maxSeats = 4 }, 1000), "a table is hosted")
		P.PokerTable:Show()
		waitTick()
		check(f.next:IsEnabled() and f.next:GetText() == "Next", "the table opened: Next goes on, got "..tostring(f.next:GetText()))
		f.next:Click()
		check(f.title._text == "The table" and ns.UI:MarkFrame("pokerbar") ~= nil and ns.UI:MarkFrame("pokerlog") ~= nil, "the table page marks the bar and the log")
		f.close:Click()
		ns:RunCommand("poker", "tour")
		check(Tour:IsShown() and f.counter._text == "Poker · 3 of 5", "/wanted poker tour continues where it was: "..tostring(f.counter._text))
		local prompted = false
		local realPrompt = ns.PromptForApp
		ns.PromptForApp = function() prompted = true end
		f.next:Click()
		f.next:Click()
		f.next:Click()
		ns.PromptForApp = realPrompt
		check(not Tour:IsShown() and ns.db.tour.poker.done and not prompted, "Finish ends the poker tour, no app prompt")
		-- Invite by name: the ad goes to the invited player by whisper (marked inv), and a realm link is offered; the
		-- invited side lists the table and is told once in chat
		addonSent = {}
		check(P.PokerNet:Invite("far friend") and P.PokerNet:Invited()[1] == "Far friend", "invited by name, capitalised")
		local whisperedAd, greeted
		for _, m in ipairs(addonSent) do
			if m.chatType == "WHISPER" and m.target == "Far friend" then
				local tag, payload = m.text:match("^(%u):%w+:%d+/%d+:(.*)$")
				local t = payload and ns.Sync:Decode(payload)
				if tag == "T" and type(t) == "table" and t.inv == 1 and t.h == ns.Store:GetOrigin() then whisperedAd = t end
				if tag == "H" then greeted = true end
			end
		end
		check(whisperedAd ~= nil and greeted, "the table's ad by whisper, and a realm link greeting")
		check(not P.PokerNet:Invite(ns.Store:GetOrigin()) and not P.PokerNet:Invite(""), "not yourself, not nobody")
		local said = {}
		local realPrint = ns.Print
		ns.Print = function(_, fmt, ...) said[#said + 1] = select("#", ...) > 0 and string.format(fmt, ...) or tostring(fmt) end
		local invAd = { id = "Remote Host#inv1", h = "Remote Host", n = "Far Den", s = 1, m = 6, sb = 5, bb = 10, lo = 200, hi = 1000, inv = 1, v = "0.1.0-dev" }
		for i = 1, 2 do
			Fire("CHAT_MSG_ADDON", "WNTD", "T:inv"..i..":1/1:"..ns.Sync:Encode(invAd), "WHISPER", "Remote Host")
		end
		ns.Print = realPrint
		local told = 0
		for _, line in ipairs(said) do if line:find("Remote Host invites you to \"Far Den\"", 1, true) then told = told + 1 end end
		local listed = false
		for _, t in ipairs(P.PokerNet:Tables()) do listed = listed or t.id == "Remote Host#inv1" end
		check(listed and told == 1, "an invitation lists the table and is told once, got "..told)
		P.PokerNet:Leave()
		P.PokerTable:Hide()
	end
	-- The daily snapshot (the data addon): with no app it fills the site's public data, and the app still counts as
	-- missing; an app's catch-up wins unless the snapshot is newer by six hours; a snapshot for another format is ignored
	do
		local savedInfo, savedLinks = WantedAppInfo, nil
		WantedAppInfo = nil
		local side = UnitFactionGroup("player")
		local function Snap(t, name, v)
			WantedSnapshot = { v = v or 1, t = t, day = "2026-10-17", [side] = { links = { { n = name, r = "Snap Realm", t = t } } } }
		end
		Snap(clock, "Snap Only")
		WantedAppCatchup = nil
		ns.Catchup:Import()
		local names = table.concat(ns.Sync:DirectoryNames(), ",")
		check(names:find("Snap Only", 1, true) and not ns.Challenges:HasApp() and WantedSnapshot == nil, "no app: the snapshot's directory, the app still missing: "..names)
		Snap(clock, "Snap Newer")
		WantedAppCatchup = { [ns.db.accountMark] = { t = clock - 7 * 3600, records = {}, links = { { n = "App Older", r = "Snap Realm", t = clock } } } }
		ns.Catchup:Import()
		names = table.concat(ns.Sync:DirectoryNames(), ",")
		check(names:find("Snap Newer", 1, true) and not names:find("App Older", 1, true), "a stale app: the snapshot's public data: "..names)
		Snap(clock, "Snap Older")
		WantedAppCatchup = { [ns.db.accountMark] = { t = clock - 3600, records = {}, links = { { n = "App Fresh", r = "Snap Realm", t = clock } } } }
		ns.Catchup:Import()
		names = table.concat(ns.Sync:DirectoryNames(), ",")
		check(names:find("App Fresh", 1, true) and not names:find("Snap Older", 1, true), "a fresh app wins: "..names)
		Snap(clock, "Wrong Format", 2)
		WantedAppCatchup = nil
		ns.Catchup:Import()
		check(not table.concat(ns.Sync:DirectoryNames(), ","):find("Wrong Format", 1, true), "another format is ignored")
		WantedAppInfo = savedInfo
	end
	-- Safety: the foot of the menu and /wanted safety open the statement with the website's Safety page to copy
	local realDialog, shown = ns.Widgets.Dialog, nil
	ns.Widgets.Dialog = function(_, options) shown = options end
	ns:RunCommand("safety", "")
	ns.Widgets.Dialog = realDialog
	check(shown and shown.title == "Safety" and shown.text:find("takes online bullying seriously", 1, true) and shown.text:find("admin@wanteddeadordead.com", 1, true)
		and shown.input and shown.input.value == "https://wanteddeadordead.com/safety", "/wanted safety: the statement and the Safety page's address to copy")
	-- /wanted setup prints the steps
	ns:RunCommand("setup", "")
	check(#printed >= 5 and printed[#printed - 4]:find("Your setup", 1, true) and printed[#printed - 1]:find("[NO] In the Wanted Battle.net group", 1, true) and printed[#printed]:find("[ok] Enemy nameplates on", 1, true), "/wanted setup prints each step with its mark")
	-- Put back
	WantedAppInfo, ns.newerVersion, ns.Bridge.clubId, ns.db.settings.siege = saved.info, saved.newer, saved.club, saved.siege
	cvars.nameplateShowEnemies, C_Club, IsSecret, ns.Print = saved.plates, saved.C_Club, saved.IsSecret, saved.Print
	ns.UI:Show("home")
end)()
-- From the cold review of the UI pass: Escape over a popup closes only it; a dialog takes its dropdown's menu with it;
-- step bar labels keep to their share; a plain frame's tooltip is on a Button the controller reaches
;(function()
	local W = ns.Widgets
	local function Escape()
		for _, name in ipairs(UISpecialFrames) do
			local frame = _G[name]
			if frame and frame:IsShown() then frame:Hide() end
		end
	end
	local function Listed(name) for _, n in ipairs(UISpecialFrames) do if n == name then return true end end return false end
	Escape()
	RunTimers()
	ns.UI:Show("board")
	local window = ns.UI:GetFrame()
	check(window:IsShown() and Listed("WantedFrame"), "the window is up, and Escape would close it")
	-- A menu open over it: Escape closes the menu, the window stays
	W:Menu({ { text = "One", onClick = function() end } })
	check(_G.WantedMenu:IsShown() and not Listed("WantedFrame") and Listed("WantedMenu"), "with a menu open, only the menu is on Escape's list")
	Escape()
	check(not _G.WantedMenu:IsShown() and window:IsShown(), "Escape closes the menu and leaves the window")
	RunTimers()
	check(Listed("WantedFrame"), "and the window goes back on the list after")
	-- A multiselect's list over Settings, the same
	local multi = W:MultiSelect(UIParent, 200, { { key = "a", label = "A" } }, function() end)
	multi:Click()
	check(multi.list:IsShown() and not Listed("WantedFrame"), "a popup open: the window comes off the list")
	Escape()
	RunTimers()
	check(not multi.list:IsShown() and window:IsShown() and Listed("WantedFrame"), "Escape closes the popup only, and the window goes back")
	-- A dialog closing takes its dropdown's menu with it
	if _G.WantedDialog and _G.WantedDialog:IsShown() then _G.WantedDialog:Hide() end
	W:Dialog({ title = "Announce", text = "x", choice = { label = "Post in", items = { { key = 1, label = "Guild" }, { key = 2, label = "Party" } }, selected = 1 } })
	local frame = _G.WantedDialog.frame
	frame.choice:Click()
	check(_G.WantedMenu:IsShown() and _G.WantedMenu.anchor == frame.choice, "the dialog's dropdown opens its menu")
	_G.WantedDialog:Hide()
	frame.choice:Hide()
	check(not _G.WantedMenu:IsShown(), "the dialog closing closes its dropdown's menu")
	RunTimers()
	-- Step bar labels and sub-lines keep to their share of the bar
	local bar = W:StepBar(UIParent, 380, { "Formed", "Sign-ups", "Starting", "Started" })
	bar:Set(3, { "", "12 going", "Thu 20:00 EDT (server 23:00)", "" })
	check(bar.dots[3].sub._w == 380 / 4 - 6 and bar.dots[3].caption._w == 380 / 4 - 6, "a step's label and sub-line are as wide as its share: "..tostring(bar.dots[3].sub._w))
	-- A stat tile's tooltip sits on a Button over it
	local tile = W:StatTile(UIParent, "Season", ns.Theme.C.gold)
	local over = W:Explain(tile, "Season", "Its days left.")
	check(over._kind == "Button" and over._parent == tile and tile.explainHit == over, "a stat tile's tooltip is on a Button the controller reaches")
end)()
-- From the review of the UI size and theme work: a dialog over a sized window takes its size; the Nearby title keeps
-- to the room beside its buttons
;(function()
	local W = ns.Widgets
	if _G.WantedDialog and _G.WantedDialog:IsShown() then _G.WantedDialog:Hide() end
	ns.UI:Show("board")
	local window = ns.UI:GetFrame()
	local realScale = window.GetEffectiveScale
	window.GetEffectiveScale = function() return 1.25 end
	W:Dialog({ title = "Sure?", text = "x" })
	check(_G.WantedDialog:GetScale() == 1.25, "a dialog over the window is the window's size: "..tostring(_G.WantedDialog:GetScale()))
	_G.WantedDialog.frame.cancel:Click()
	window.GetEffectiveScale = realScale
	ns.UI:GetFrame():Hide()
	W:Dialog({ title = "Alone", text = "x" })
	check(_G.WantedDialog:GetScale() == 1, "with no window under it, the dialog is UIParent's size")
	_G.WantedDialog.frame.cancel:Click()
	RunTimers()
	-- The Nearby title: the view's name and count when they fit, the count alone when they don't
	local title
	for _, fs in ipairs(Mock.fontStrings) do
		if type(fs._text) == "string" and fs._parent and fs._parent._parent == _G.WantedNearbyFrame and rawget(fs, "fitWidth") then title = fs end
	end
	check(title, "the Nearby window's title is fitted to its room")
	-- On the Last hour tab, whose title names its view
	local nearbySettings = ns.db.settings.detect
	local realTab = nearbySettings.tab
	nearbySettings.tab = "hour"
	title._w = 30
	ns.NearbyWindow:Refresh()
	local function Plain(t) return (tostring(t):gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")) end
	check(not Plain(title._text):find("%a"), "squeezed: the count alone, got "..Plain(title._text))
	title._w = 200
	ns.NearbyWindow:Refresh()
	check(Plain(title._text):find("%a"), "with room: the view's name too, got "..Plain(title._text))
	nearbySettings.tab = realTab
	ns.NearbyWindow:Refresh()
end)()
-- The menu: Poker's entry at its foot, directly above Safety
;(function()
	ns.UI:Show("board")
	local poker, safety
	for _, f in ipairs(Mock.created) do
		local label = rawget(f, "label")
		if f._kind == "Button" and type(label) == "table" and label._text == "Poker" and rawget(f, "key") == "poker" then poker = f end
		if f._kind == "Button" and type(label) == "table" and label._text == "Safety" then safety = f end
	end
	check(poker and poker._point[1] == "BOTTOMLEFT" and safety._point[1] == "BOTTOMLEFT" and poker._point[3] == safety._point[3] + safety._h,
		"Poker sits at the foot of the menu, directly above Safety: "..tostring(poker and poker._point[3]).." over "..tostring(safety and safety._point[3]))
end)()
-- What's new 1.28.0 is signed in the maintainer's words: the sign-off is the note's last line, with no author line
-- under it; older notes keep theirs
;(function()
	local N = ns.WhatsNew
	N:Show()
	local body = _G.WantedWhatsNewFrame and _G.WantedWhatsNewFrame.body
	local text = body and body._text or ""
	local note = ns.WHATS_NEW[1]
	check(note.version == "1.28.0" and note.signed and text:find("— Chris aka xmadness", 1, true), "1.28.0's note is signed")
	check(not text:find("The maintainers of Wanted", 1, true), "with no author line under its sign-off")
	_G.WantedWhatsNewFrame:Hide()
end)()
print("wanted smoke: setup checks pass")
-- Influence races: the catch-up's races read and cleaned; presence on a race point every 30 s inside its radius, on the
-- same WANTEDP1 line as a capture point's, and none outside it, while it can't count or outside the race; the Guild
-- Wars page in Siege's place; the HUD in the race's zone while it runs
;(function()
	local R, C, db = ns.Races, ns.Captures, ns.db
	local real = { C_Map = C_Map, IsMounted = IsMounted, C_Log = C_Log, siege = db.settings.siege, presence = db.presence, Broadcast = ns.Sync.BroadcastPlugin }
	-- What we tell our side, live (Races' live numbers)
	local told = {}
	ns.Sync.BroadcastPlugin = function(_, tag, t) told[#told + 1] = { tag = tag, t = t, at = clock } return true end
	local mapId, px, py = 1424, 0.573, 0.37
	C_Map = { GetBestMapForUnit = function() return mapId end, GetPlayerMapPosition = function() return { x = px, y = py } end,
		GetMapInfo = function() return { mapType = 3 } end }
	local mounted = false
	IsMounted = function() return mounted end
	local start = clock + 600
